SELECT 'moj-all-verified-judgments-review-002-chunk-179' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3e7aae23-9245-5ff1-80fb-04a176931dbb","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة املستأجر بفسخ إجارة عقار لتغير أجرة املثل- تعديل قيمة اإليجار باملثل أو فسخ العقد -وجوب الوفاء بالعقود- احلكم برد الدعوى .","document_number":"34194141","case_number":"33141857","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":"الدائرة احلقوقية الثانية املتضمن أنه بدراسة الصك وصورة ضبطه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"إجارة -مطالبة املستأجر بفسخ إجارة عقار لتغير أجرة املثل- تعديل قيمة اإليجار باملثل أو فسخ العقد -وجوب الوفاء بالعقود- احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34194141 :‬‬\n                    ‫َر ْق ُم الدعوى‪33141857 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34266654‬تاريخه‪1434/7/12 :‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة املســتأجر بفســخ إجــارة عقــار لتغيــر أجــرة املثــل‪-‬‬\n‫تعديــل قيمــة اإليجــار باملثــل أو فســخ العقــد ‪ -‬وجــوب الوفــاء بالعقــود‪-‬‬\n                                                      ‫احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n                    ‫قول اهلل تعالى‪ (( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــن بــأن املدعــى عليــه اســتأجر مــن موكليــه العقــار‬\n‫املوصــوف يف الدعــوى للمــدة واألجــرة املذكوريــن يف دعــواه وأنــه قــد‬\n‫مضــى جــزء مــن مــدة العقــد ثــم ارتفعــت أســعار اإليجــار يف املنطقــة عــن‬\n‫األجــرة املتعاقــد عليهــا‪ ،‬لــذا فقــد طلــب إلــزام املدعــى عليــه بتعديل قيمة‬\n‫األجــرة لتكــون كأجــرة املثــل أو فســخ العقــد‪ ،‬أقــر وكيــل املدعــى‬\n‫عليــه مبــا جــاء يف الدعــوى وقــرر بــأن موكلــه ال يوافــق علــى زيــادة‬\n‫األجــرة ألن بينــه وبــن املدعــن عقــد وهــو متمســك بــه‪ ،‬املدعــى عليــه‬\n‫بيــده عقــد إجــارة صحيــح واهلل عــز وجــل يقــول (( يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود))‪ ،.‬قضــت احملكمــة بــرد دعــوى املدعــن جتــاه املدعــى‬\n‫عليــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه وكيــل املدعــن‪،‬‬\n                      ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n                                                                                     ‫‪276‬‬\n\f      ‫العامــة‬\n          ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء حضر املدعي وكالة ‪........‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪........‬حــال كونــه وكيــا عــن ‪........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪........‬و ‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪........‬و‪........‬اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪........‬وذلــك مبوجــب الوكالتــن الصــادرة مــن كتابــة‬\n      ‫عــدل الدمــام الثانيــة برقــم ‪ 6424‬و ‪1433/2/3‬ه ـ جلــد ‪ 9830‬ورقــم‬\n      ‫‪ 7225‬يف ‪1433/2/8‬ه ـ جلــد ‪ 9838‬كمــا حضــر املدعــى عليــه وكالــة‬\n      ‫‪........‬الســعودي مبوجــب الســجل املدنــي رقــم ‪........‬بصفتــه وكيــا عــن‬\n      ‫‪........‬مبوجــب الســجل املدنــي رقــم ‪........‬مبوجــب الوكالــة رقــم ‪17382‬‬\n      ‫وتاريــخ ‪1432/5/8‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء‬\n      ‫و قــال املدعــي وكالــة يف حتريــر دعــواه إن موكلــي هــم ورثــة ‪........‬‬\n      ‫مبوجــب صــك حصــر اإلرث الصــادر مــن محكمــة الدمــام الكبــرى‬\n      ‫برقــم ‪ 3/5/22‬يف ‪1405/1/15‬ه ـ وقــد خلــف ملوكلــي عمــارة تقــع يف‬\n      ‫حــي ‪ ........‬باألحســاء اململوكــة مبوجــب الصــك الصــادر مــن كتابــة‬\n      ‫عــدل األحســاء برقــم ‪ 1/107‬وتاريــخ ‪1394/1/25‬ه ـ و هــي عبــارة عــن‬\n      ‫خمســة محــات وشــقة أرضيــة و شــقتني علويــة و قــد أجرهــا وكيــل‬\n‫‪277‬‬\n\f‫موكلــي يف تاريــخ ‪1423/7/16‬ه ـ مبوجــب وكالــة مــن موكلـ ّـي ملــدة‬\n‫عشرين سنة تبدأ من ‪1424/1/1‬هـ وتنتهي يف ‪1444/12/30‬هـ بأجرة‬\n‫ســنوية وقدرهــا ثالثــون ألــف ريــال وقــد مضــى علــى هــذه األجــرة تســع‬\n‫ســنوات وقــد زادت وارتفعــت أســعار اإليجــار يف املنطقــة وأجــرة مثيالتهــا‬\n‫اآلن مائــة و عشــرة آالف ريــال وموكلـ ّـي يطالبــون بإلــزام املدعــى عليــه‬\n‫بتعديــل قيمــة اإليجــار ليكــون كأجــرة املثــل أو فســخ العقــد هــذه‬\n‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي وكالــة‬\n‫كلــه صحيــح فيمــا يتعلــق باألجــرة ومدتهــا ومقدارهــا وموكلـ ّـي ال‬\n‫يوافــق علــى زيــادة األجــرة وبينــه وبــن املدعــن عقــد وموكلــي متمســك‬\n‫بهــذا العقــد هكــذا أجــاب جــرى عــرض الصلــح بــن الطرفني ولــم يتفقا‬\n‫وقــال املدعــى عليــه وكالــة إن مقــدار أجــرة العمــارة يف الوقــت احلاضــر‬\n‫هــو ســتون ألــف ريــال وقــد أجرهــا موكلــي بهــذه األجــرة ومــا ذكــره‬\n‫املدعــي وكالــة يف اجللســة املاضيــة مبالــغ فيــه وقــال املدعــي وكالــة مــا‬\n‫ذكرتــه يف اجللســة املاضيــة هــو الصحيــح لــذا قــررت الكتابــة لقســم‬\n‫اخلبــراء بهــذه احملكمــة لتقديــر أجــرة العمــارة يف الوقــت احلاضــر ثــم‬\n‫وردنــا قــرار قســم اخلبــراء رقــم ‪ 139‬يف ‪143/03/02‬ه ـ املتضمــن نصــه‬\n‫(نفيدكــم بأنــه مت االســتعانة بأهــل اخلبــرة يف هــذا املجــال لالســتئناس‬\n‫برأيهــم و قــد مت التوصــل إلــى أن هــذا العقــار يقــدر يف الوقــت احلالــي‬\n‫بأجــرة ســنوية مببلــغ و قــدره ســبعون ألــف ريــال هــذا مــا مت التوصــل‬\n‫إليــه) انتهــى نصــه و بعرضــه علــى الطرفــن قــال املدعــي وكالــة إن‬\n‫مــا جــاء يف هــذا القــرار و تقديرهــم قريــب مــن الصحــة و ال زلــت علــى‬\n‫املطالبــة بفســخ العقــد أو تعديــل األجــرة و قــال املدعــى عليــه وكالــة‬\n‫إننــي غيــر مقتنــع بتقديــر قســم اخلبــراء و مــع موكلــي عقــد صحيــح‬\n\n\n                                                                                    ‫‪278‬‬\n\f      ‫ملــدة عشــرين ســنة مضــى عليــه أحــد عشــر ســنة و بقــي تســع ســنوات و‬\n      ‫متمســك بــه موكلــي فبنــاء علــى مــا تقــدم ومبــا أنــه بيــد املدعــى عليــه‬\n      ‫أصالــة عقــد إيجــار صحيــح وعقــد اإليجــار ملــزم للطرفــن ال ســيما مــع‬\n      ‫مضــي جــزء كبيــر منــه مــع عــدم املعارضــة وزيــادة األجــرة بعــد مضــي‬\n      ‫الوقــت غيــر مســوغ للمدعــي يف املطالبــة بفســخ العقــد أو زيــادة األجــرة‬\n      ‫لقولــه تعالــى‪ (( :‬يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود ‪ )...‬اآليــة ولــو ســاغ‬\n      ‫ذلــك ألدى إلــى عــدم اســتقرار العقــود وتضــرر الطــرف اآلخــر وتقديــر‬\n      ‫قســم اخلبــراء ألجــرة العقــار يف الوقــت احلاضــر ليــس فيــه زيــادة فاحشــة‬\n      ‫كمــا ذكــر املدعــي يف دعــواه ويف حــدود الزيــادة املعقولــة لــذا فلــم‬\n      ‫يثبــت لــي حــق للمدعــن فيمــا يطالبــون بــه ورددت دعواهــم جتــاه املدعــى‬\n      ‫عليــه وبذلــك حكمــت وبإعــان احلكــم قــرر املدعــى عليــه قناعتــه فيمــا‬\n      ‫قــرر املدعــي وكالــة عــدم القناعــة وطلب االســتئناف وأفهمتــه باملراجعة‬\n      ‫يــوم االثنــن ‪1434/4/22‬ه ـ الســتالم نســخت احلكــم واالعتــراض عليه‬\n      ‫خــال ثالثــن يــوم وإال ســقط حــق موكلــه باالعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/14‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/8/9‬ه ـ فتحــت اجللســة‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫وبرفقهــا القــرار رقــم ‪34266654‬وتاريخ‪1434/7/12‬ه ـ الصــادر مــن‬\n      ‫الدائــرة احلقوقيــة الثانيــة املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫لــذا جــرى التهميــش وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":276,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed4f9feb54d5b279b5f725dcc0e12c084af69d03843062f40d5acf62b7e7f8d5","normalized_text_hash":"5949cc61cee74af7eeda6380240d374d8cf7973be07f5e941a4e7b4502f8aa4b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p276-34194141"},{"id":"230e539d-7b0e-5d01-80d2-c6575b6ef396","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخال بشرط من شروط العقد -من ملك شيئا استوفاه بنفسه أو نائبه -املستأجر ميلك املنفعة -احلكم برد الدعوى لعدم مخالفة املدعى عليه ملقتضى العقد .","document_number":"34251380","case_number":"34202800","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/25","year":"1434","subject":"إجارة -إخال بشرط من شروط العقد -من ملك شيئا استوفاه بنفسه أو نائبه -املستأجر ميلك املنفعة -احلكم برد الدعوى لعدم مخالفة املدعى عليه ملقتضى العقد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/25 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34251380 :‬‬\n                    ‫َر ْق ُم الدعوى‪34202800 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34362571‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــال بشــرط مــن شــروط العقــد ‪ -‬مــن ملــك شــيئا اســتوفاه‬\n‫بنفســه أو نائبــه ‪ -‬املســتأجر ميلــك املنفعــة ‪ -‬احلكــم بــرد الدعــوى‬\n                        ‫لعــدم مخالفــة املدعــى عليــه ملقتضــى العقــد ‪.‬‬\n\n\n\n‫جــاء يف كشــاف القنــاع ‪(98/9‬ولــو شــرط عليــه اســتيفاءها أي املنفعــة‬\n‫بنفســه فســد الشــرط ولــم يجــز الوفــاء بــه ألنــه شــرط ينــايف مقتضــى‬\n‫العقــد إذ مقتضــاه امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبــه)‬\n                                                                         ‫أ‪.‬هـ‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه مبطالبتــه بفســخ عقــد اإليجــار‬\n‫ملخالفتــه العقد‪،‬حيــث اســتأجر املدعــى عليــه مــن املدعــي عمــارة‬\n‫بأجــرة ســنوية قدرهــا مائتــان وســتون ألــف ريــال علــى أن يؤجرهــا شــقق‬\n‫مفروشــة وقــد أجرهــا املدعــى عليــه لشــركة وهــو يخالــف العقــد وللبنــد‬\n‫الثانــي‪ ،‬صــادق املدعــى عليــه علــى اســتئجار العمــارة وأنكــر مخالفــة‬\n‫العقــد والنظــام‪ ،‬بينــة املدعــي عقــد اإليجــار‪ ،‬العقــد نــص علــى أحقيــة‬\n‫املســتأجر بتأجيــر العمــارة للغيــر دون الرجــوع للمالــك وهــو طبــق مــا دفــع‬\n‫بــه املدعــى عليــه‪ ،‬ومبــا أن املدعــى عليــه لم يخالف مقتضــى العقد املبرم‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫بينهمــا واملســلمون علــى شــروطهم وألن املســتأجر ملــك املنفعــة مبجــرد‬\n      ‫العقــد ولــه التصــرف فيهــا فيمــا ال يضــر بالعــن املســتأجرة قــال صاحــب‬\n      ‫الكشــاف (‪( )98/9‬ولــو شــرط عليــه اســتيفاءها أي املنفعــة بنفســه‬\n      ‫فســد الشــرط ولــم يجــز الوفــاء بــه ألنــه شــرط ينــايف مقتضــى العقــد‬\n      ‫إذ مقتضــاه امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبــه)أ‪ ،.‬وهــذا‬\n      ‫علــى كــون صحــة شــرط املدعــي أن تكــون األجــرة يوميــة ولــم ينــص‬\n      ‫علــى ذلــك بالعقــد بــل نــص علــى خالفــه‪ ،‬لــم يثبــت اســتحقاق املدعــي ملــا‬\n      ‫يطلبــه مــن فســخ العقــد لعــدم مخالفــة املدعــى عليــه ملقتضــاه التعاقــدي‬\n      ‫والشــرعي‪ ،‬رد دعــوى املدعــي‪ ،‬اعتــرض املدعــي علــى احلكــم بالئحــة‬\n      ‫اعتراضيــة‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n                                            ‫االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n      ‫الســبت املوافق‪1434/5/25‬هـ لدي أنا ‪ ......‬القاضي باحملكمة العامة‬\n      ‫بينبــع بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n      ‫‪ 34202800‬وتاريــخ ‪1434/5/1‬ه ـ واملقيــدة برقــم ‪ 341081258‬وتاريــخ‬\n      ‫‪1434/5/1‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر ‪......‬‬\n      ‫ســعودي بالهويــة الوطنيــة رقــم ‪ ......‬وحضــر حلضــوره ‪ ......‬ســعودي بالهويــة‬\n      ‫الوطنيــة رقــم ‪ ......‬أدعــى املدعــي قائــا إنــه بتاريخ‪1434/4/4‬ه ـ أجــرت‬\n      ‫علــى املدعــى عليــه ‪.........‬الكائنــة أمــام احملكمــة العامــة بينبــع بأجــرة‬\n      ‫ســنوية مقدارهــا مائتــان وســتون ألــف ريــال على دفعتني كل ســتة أشــهر‬\n      ‫وقــد دفــع املئتــان والســتني ألــف كاملــة علــى أن يؤجرهــا شــقق مفروشــة‬\n‫‪281‬‬\n\f‫نظاميــة وقــد أجــر املدعــى عليــه العمــارة لشــركة وهــذا يخالــف النظــام‬\n‫ويخالــف العقــد ومــا جــاء يف بنــد رقم‪2‬ونصــه يتعهــد املســتأجر بعــدم‬\n‫التنــازل عــن العقــار لطــرف ثالــث مــا لــم يحصــل علــى موافقــة خطيــه‬\n‫مــن الطــرف األول أطلــب فســخ العقــد الــذي أبــرم بيننــا وأن يســلمني‬\n‫العقــار كمــا أســتلمه منــي هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n‫دعــوى املدعــي أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه مــن كونــه‬\n‫أجــر لــي العقــار املوصــوف بالصفــة التــي ذكرهــا فصحيــح ومــا ذكــره‬\n‫مــن أنــي خالفــت النظــام فغيــر صحيــح ولــم أخالــف العقــد أيضــا وقــد‬\n‫أجــرت للشــركة كشــقق مفروشــة وال يوجــد بالنظــام مــا مينــع مــن ذلــك‬\n‫هــذا جوابــي وبطلــب البينــة مــن املدعــي طلــب مهلــة وأجبتــه لطلبــه ويف‬\n‫جلســة أخــرى حضــر الطرفــان وبســؤال املدعــي للبينــة قــال بينتــي العقــد‬\n‫وبطلبــه أبــرز عقــدا صــادرا مــن مكتــب ‪ ...........‬للعقــار بينبــع وجدتــه‬\n‫يتضمــن تأجيــر املدعــي للمدعــى عليــه عمــارة مكونــة مــن أربعــة أدوار‬\n‫بحــي العمــودي ملــدة عشــر ســنوات اعتبــارا مــن تاريــخ ‪1434/4/1‬ه ـ‬\n‫مببلــغ مائتــن وســتني ألــف ريــال للســنة واإليجــار لكامــل العمــارة ســوى‬\n‫ثــاث محــات جتاريــة وأنــه يحــق للمســتأجر اإليجــار للغيــر دون الرجــوع‬\n‫للمالك وأن اإليجار شــقق مفروشــة اســتثمارية وصيانتها على املســتأجر‬\n‫مــن اســتثماره ‪ .‬أ ‪ .‬ه ـ مضمونــه وبســؤال املدعــى عليــه عــن العقــد املبــرم‬\n‫بينــه وبــن الشــركة قــال أطلــب مهلــة لذلــك وأضــاف ولكــن مت النــص‬\n‫يف عقــد اإليجــار علــى أنــه يحــق لــي إيجــار الغيــر بــدون الرجــوع للمالــك‬\n‫وهــذا يناقــض مــا ذكــره مــن أننــي خالفــت العقــد يف البنــد الثانــي ويف‬\n‫جلســة أخــرى حضــر املدعــي واملدعــى عليــه وبســؤال املدعــى عليــه‬\n‫عمــا طلــب منــه أبــرز عقــدا صــادرا مــن مكتــب ‪ ...‬للخدمــات العامــة‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫والعقاريــة محــررا بتاريــخ ‪2013/3/1‬م ويتضمــن تأجيــر املدعــى عليــه‬\n      ‫للمواطــن ‪ ......‬العمــارة محــل الدعــوى بصفتهــا شــقق فندقيــة مجهــزة‬\n      ‫للســكن وذلــك لغــرض إســكان عمــال شــركته مــدة ســنتني وقيمــة‬\n      ‫األجــرة ســبعمائة وتســعة وعشــرون ألــف ريــال للســنة أ ‪ .‬ه ـ املقصــود‬\n      ‫منــه وبتالوتــه علــى املدعــي قــال إننــي اتفقــت معــه علــى تأجيــره إيجــارا‬\n      ‫يوميــا ثــم ســألت املدعــي هــل وقعــت علــى العقــد مبــا أضيــف إليــه قــال‬\n      ‫نعــم ولكننــي ال أقــرأ وال أكتــب هكــذا قــال فبنــاء علــى مــا ســبق مــن‬\n      ‫الدعــوى واإلجابــة ومبــا أن املدعــي طلــب فســخ العقــد املبــرم بينــه وبــن‬\n      ‫املدعــى عليــه إلدعائــه مخالفــة العقــد وذلــك بتأجيــره لشــركة فجــرى‬\n      ‫منــي اإلطــاع علــى العقــد املبــرم بينهمــا املرصــود مضمونــه بعاليــه وإذا‬\n      ‫بــه ينــص يف البنــد الثانــي مــن امللحوظــات بأنــه يحــق للمســتأجر اإليجــار‬\n      ‫للغيــر دون الرجــوع للمالــك أ ‪ .‬ه ـ ويف البنــد الثالــث أن اإليجــار شــقق‬\n      ‫مفروشــة اســتثمارية وصيانتــه علــى املســتأجر أو مــن اســتأجره أ ‪ .‬ه ـ‬\n      ‫وباالطــاع علــى مــا أبرمــه املدعــى عليــه مــع مــن أجــره املرصــود مضمونه‬\n      ‫بعاليــه وإذا بــه ينــص علــى أن اإليجــار لشــقق فندقيــة مجهــزة للســكن‬\n      ‫ونــص علــى عــدد الســاكنني وهــم مائــة وخمســة وثالثــن فــردا أ ‪ .‬ه ـ‬\n      ‫فبنــاء علــى مــا ســبق وألن املدعــى عليــه لــم يخالــف مقتضــى العقــد املبــرم‬\n      ‫بينهمــا واملســلمون علــى شــروطهم وألن املســتأجر ملــك املنفعــة مبجــرد‬\n      ‫العقــد ولــه التصــرف فيهــا فيمــا ال يضــر بالعــن املســتأجرة قــال صاحــب‬\n      ‫الكشــاف(‪()98/9‬ولو شــرط عليــه اســتيفاءها أي املنفعــة بنفســه فســد‬\n      ‫الشــرط ولــم يجــز الوفــاء بــه ألنه شــرط ينــايف مقتضى العقــد إذ مقتضاه‬\n      ‫امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبه)أ‪.‬ه ـ وهــذا علــى كــون‬\n      ‫صحــة شــرط املدعــي أن تكــون األجــرة يوميــة ولــم ينــص علــى ذلــك يف‬\n\n\n‫‪283‬‬\n\f‫العقــد بــل نــص علــى خالفــه ولــكل مــا ســبق فلــم يثبــت لــدي اســتحقاق‬\n‫املدعــي ملــا يطلبــه مــن فســخ العقــد لعــدم مخالفــة املدعــى عليــه ملقتضــاه‬\n‫التعاقــدي والشــرعي ورددت دعــوى املدعــي وأخليــت ســبيل املدعــى‬\n‫عليــه هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى املدعــي قــرر عــدم‬\n‫قناعتــه باحلكــم وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــه‬\n‫فجــرى تســليمه نســخة مــن صــك احلكــم وأفهــم بــأن لــه ثالثــن يومــا‬\n‫مــن تاريــخ هــذا اليــوم وإذا مضــت املــدة ولــم يقــدم اعتراضــه خاللهــا‬\n‫اكتســب احلكــم الصفــة القطعيــة وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/06/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق ‪ 1434/10/22‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثانيــة عشــر وفيهــا حضــر املدعــي وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بكتــاب فضيلــة‬\n‫رئيــس محكمــة االســتئناف رقــم ‪ 341081258‬وتاريــخ ‪1434/8/17‬ه ـ‬\n‫مرفقــا بــه قــرار الدائــر احلقوقيــة الثانيــة رقــم ‪ 34293510‬وتاريــخ‬\n‫‪1434/8/10‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة «وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا ملالحظــة مــا يلــي‬\n‫‪ -1‬لــم يطلــب فضيلــة ناظــر القضيــة مــن املدعــي مــا يثبــت متلكــه للعمارة‬\n‫املؤجــرة ولــم يرفــق مــا يفيــد ذلــك بــأوراق املعاملــة ‪ -2‬تصويــب األخطــاء‬\n‫اإلمالئيــة والنحويــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم « أ‪ .‬ه ـ بختــم وتوقيع أصحــاب الفضيلة قضاة الدائرة‬\n‫ولوجاهــة مــا أشــار إليــه أصحــاب الفضيلــة ســددهم اهلل فقــد طلبــت مــن‬\n‫املدعــي مــا يثبــت ملكيتــه للعقــار فأبــرز الصــك الشــرعي الصــادر مــن‬\n‫كتابــة عــدل ينبــع برقــم ‪ 3/2/1927‬وتاريــخ ‪1422/3/11‬ه ـ املتضمــن‬\n\n\n                                                                                      ‫‪284‬‬\n\f      ‫متلــك املدعــي للعمــارة املوصوفــة محــل الدعــوى وأمــا بخصــوص اخلطــأ‬\n      ‫املشــار إليــه يف الســطر اخلامــس فــإن صحتــه (املائتــن و الســتني ألــف)‬\n      ‫ويف الســطر اخلامــس والعشــرين صحــة العبــارة الــواردة فيــه (ورددت‬\n      ‫دعــوى املدعــي) بــدال مــن املدعــى عليــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                 ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر ‪1434/10/22‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بينبــع املســاعد الشــيخ ‪ ......‬برقــم ‪341081258‬‬\n      ‫وتاريــخ ‪1434/10/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلتــه برقــم‬\n      ‫‪ 34251380‬وتاريــخ ‪1434/6/25‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ......‬ضــد ‪، ......‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":280,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b377d1f42a7ed9c9930d4fc770702dccf3f2fc1237fb914327fdea7e43499efc","normalized_text_hash":"86a45c8c5d661a28f7c97b1af868c58d4b61974ad607be4e862d1e6474a552aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p280-34251380"},{"id":"22247769-4375-53e1-b580-1ecae33f0976","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لعدم معرفة عنوان املدعى عليه -العقد بينة املدعي -احلكم بإخاء العن- الغائب على حجته متى حضر.","document_number":"34309503","case_number":"34232323","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/30","year":"1434","subject":"إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لعدم معرفة عنوان املدعى عليه -العقد بينة املدعي -احلكم بإخاء العن- الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/30 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34309503 :‬‬\n                    ‫َر ْق ُم الدعوى‪34232323 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34325311‬تاريخه‪1434/9/24:‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬ســماع الدعــوى غيابيـ ًا لعــدم معرفــة‬\n‫عنــوان املدعــى عليــه ‪ -‬العقــد بينــة املدعــي ‪ -‬احلكــم بإخــاء العــن‪-‬‬\n                                        ‫الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n                               ‫قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائب عن مجلــس احلكم بأن املدعى‬\n‫عليــه اســتأجر غرفــة يف العمــارة الواقعــة يف ‪ ......‬بينبــع الصناعيــة بأجــرة‬\n‫ـداء مــن ‪1433/09/15‬ه ـ‬    ‫شــهرية قدرهــا ألــف ريــال تدفــع ملــدة ســنة ابتـ ً‬\n‫إلــى ‪1434/09/15‬ه ـ وقــد ســلمه مــن األجــرة أربعــة أشــهر وإنــه مــن‬\n‫تاريــخ ‪1434/02/15‬ه ـ حتــى تاريــخ اليــوم لــم يســتلم منــه مبلــغ األجــرة‬\n‫الــذي يخصهــا وقــدره ســتة آالف ريــال وقــد حلقــه الضــرر مــن تعطيــل‬\n‫الغرفــة وعــدم دفــع األجــرة ويطلــب إلــزام املدعــى عليــه بإخــاء العقــار‬\n‫فــور ًا هكــذا ادعــى‪ ،‬املدعــى عليــه ال يعــرف لــه عنــوان حيــث جــرى‬\n‫مخاطبــة عملــه لتبليغــه فــوردت اإلفــادة بأنــه منقطــع عــن العمــل فجــرى‬\n‫ســماع الدعــوى غيابي ـاً‪ ،‬بينــة املدعــي عقــد اإليجــار ‪ ،‬ويســري العقــد‬\n‫ملــدة ســنة مــن تاريخ‪1433/09/15‬ه ـ ‪ ،‬ولتعــذر إبــاغ املدعــى عليــه ‪،‬‬\n\n                                                                                     ‫‪286‬‬\n\f      ‫وملــا أبــداه املدعــي مــن وقــوع الضــرر عليــه يف تأخــر املدعــى عليــه يف‬\n      ‫دفــع األجــرة وعــدم إخــاء الغرفــة محــل الدعــوى‪ ،‬ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم (ال ضــرر وال ضــرار) وألن هــذا مــن الضــرر الــذي يلحــق‬\n      ‫النــاس يف أموالهــم وقــد جــاءت الشــريعة اإلســامية بحفظــه وألن العقــد‬\n      ‫بينــة املدعــي وينتهــي أجلــه يف التاريــخ الــذي ذكــره املدعــي‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم علــى املدعــى عليــه الغائــب بإخــاء الغرفــة املذكــورة يف‬\n      ‫الدعــوى يف أجــل انتهــاء العقــد يف‪1434/09/15‬ه ـ والغائــب علــى حجتــه‬\n      ‫متــى حضــر‪ ،‬رفــع احلكــم إلــى محكمــة االســتئناف لتدقيقــه‪ ،‬صــدق‬\n      ‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                  ‫مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة لــه مــن‬\n                                           ‫بينبــع والقائــم بعمــل القاضــي ‪......‬وبنـ ً‬\n      ‫فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بينبــع برقــم ‪34232323‬‬\n      ‫وتاريــخ ‪1434/05/20‬ه ـ املقيــدة باحملكمــة برقــم ‪341228955‬‬\n      ‫وتاريــخ ‪1434/05/20‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ا يف‬ ‫املدنــي رقــم ‪......‬وادعــى علــى الغائــب عــن املجلــس الشــرعي‪ ......‬قائـ ً‬\n      ‫دعــواه إنــه بتاريــخ ‪1433/09/07‬ه ـ مت االتفــاق بينــي وبــن املدعــى عليــه‬\n      ‫علــى أن يســتأجر املدعــى عليــه غرفــة يف العمــارة الواقعــة يف حــي ‪......‬‬\n      ‫بينبــع الصناعيــة بأجــرة شــهرية قدرهــا (‪ ) 1,000‬ألــف ريــال تدفــع ملــدة‬\n      ‫ـداء مــن ‪1433/09/15‬ه ـ إلــى ‪1434/09/15‬ه ـ وقــد ســلمني‬             ‫ســنة ابتـ ً‬\n‫‪287‬‬\n\f‫مــن األجــرة أربعــة أشــهر وإنــه مــن تاريــخ ‪1434/02/15‬ه ـ حتــى تاريــخ‬\n‫اليــوم لــم اســتلم منــه مبلــغ األجــرة الــذي يخصهــا وقــدره ( ‪ ) 6,000‬ســتة‬\n‫آالف ريــال أطلــب إلــزام املدعــى عليــه بإخــاء العقــار فــور ًا هكــذا ادعى‬\n‫وقــد ســبق الكتابــة إلدارة األمــن الصناعــي بينبــع الصناعيــة باخلطــاب‬\n‫ذي الرقــم‪ 341367049‬وتاريخ‪1434/06/11‬ه ـ إلبــاغ املدعــى عليــه‬\n‫مبوعــد اجللســة يــوم الســبت املوافق‪1434/06/24‬ه ـ الســاعة الثامنــة‬\n‫والنصــف فوردنــا خطابهــم ذي الرقــم‪ 125298‬وتاريخ‪1434/06/20‬ه ـ‬\n‫املتضمن‪0‬إشــارة إلــى خطابكــم رقــم‪ ......‬وتاريخ‪1434/06/11‬ه ـ‬\n‫املتضمــن طلبكــم تكليــف املوظــف ‪......‬مبراجعتكــم عليــه نفيدكــم‬\n‫بــأن املذكــور منقطــع عــن العمــل مــن تاريخ‪1433/12/01‬ه ـ وحتــى‬\n‫تاريخــه ومرفــق لكــم كامــل املعاملة)ا‪.‬ه ـ وبســؤال املدعــي عــن بينتــه‬\n‫التــي تشــهد بصحــة دعــواه فأبــرز عقــد إيجــار صــادر مــن مكتــب‬\n‫‪...‬للعقــار وإدارة األمــاك برقــم‪ 59‬وتاريخ‪1433/09/07‬ه ـ وباالطــاع‬\n‫عليــه وجدتــه مطابــق ملــا ذكــره املدعــي يف دعــواه و‪......‬وتوقيــع الطــرف‬\n‫األول ‪......‬و‪ ......‬وتوقيــع الطــرف الثانــي ‪ ......‬ثــم جــرى منــي ســؤال‬\n‫املدعــي هــل لديــه زيــادة بينــه علــى مــا ذكــره فأجــاب بقولــه ليــس لــدي‬\n‫ســوى مــا ذكرتــه ويف جلســة أخــرى لــدي أنــا ‪......‬القاضــي باحملكمــة‬\n‫العامــة بينبــع والقائــم بعمــل املكتــب القضائــي اخلامــس مبوجــب قــرار‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد رقــم ‪341935902‬‬\n‫وتاريخ‪1434/08/09‬ه ـ ففــي يــوم االثنــن املوافــق ‪ 1434/08/29‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه وال‬\n‫وكيلــه وجــرى عــرض مــا ســبق علــى املدعــي فصــادق علــى مــا جــاء فيه‪،‬‬\n‫وأضــاف‪ :‬إنــي قــد حلقنــي الضــرر مــن تعطيــل الغرفــة املذكــورة وعــدم‬\n\n\n                                                                                    ‫‪288‬‬\n\f      ‫دفــع األجــرة وتغيــب املدعــى عليــه وال يعــرف لــه عنــوان أطلــب احلكــم‬\n      ‫بإلزامــه بإخــاء الغرفــة املذكــورة النتهــاء األجــل يف‪1434/09/15‬ه ـ‬\n      ‫هكــذا قــال ‪ ،‬وعليــه طلبــت مــن املدعــي البينــة علــى صحــة دعــواه فأبرز‬\n      ‫العقــد املــدون علــى أوراق مكتــب ‪...‬للعقار برقم‪ 59‬يف ‪1433/09/07‬هـ‬\n      ‫املتضمــن تأجيــر املدعــي للمدعــى عليــه للغرفــة بعمارتــه الكائنة يف حي‬\n      ‫‪ ،......‬ويســري العقــد ملــدة ســنة مــن تاريخ‪1433/09/15‬ه ـ وقــد جــرى‬\n      ‫إرفــاق صــورة مــن العقــد يف املعاملــة وعليــه وملــاء جــاء يف الدعــوى ولتعــذر‬\n      ‫إبــاغ املدعــى عليــه ‪ ،‬وملــا أبــداه املدعــي مــن وقــوع الضــرر عليــه يف تأخــر‬\n      ‫املدعــى عليــه يف دفــع األجــرة وعــدم إخالء الغرفة محل الدعوى‪ ،‬ولقوله‬\n      ‫صلــى اهلل عليــه وســلم‪»:‬ال ضــرر وال ضــرار» وألن هــذا مــن الضــرر الــذي‬\n      ‫يلحــق النــاس يف أموالهــم وقــد جــاءت الشــريعة اإلســامية بحفظــه وألن‬\n      ‫العقــد بينــة املدعــي وينتهــي أجلــه يف التاريــخ الــذي ذكــره املدعــي لــذا‬\n      ‫فقــد حكمــت علــى املدعــى عليــه الغائــب بإخــاء الغرفــة املذكــورة يف‬\n      ‫الدعــوى يف أجــل انتهــاء العقــد يف‪1434/09/15‬ه ـ والغائــب علــى حجتــه‬\n      ‫متــى حضــر وقــررت رفــع احلكــم مــع املعاملــة إلــى محكمــة االســتئناف‬\n      ‫لتدقيقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/29‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪....../‬القاضي باحملكمــة العامــة بينبــع واملســجل بعــدد ‪......‬‬\n      ‫وتاريــخ ‪1434/8/30‬ه ـ املتضمــن دعــوى ‪......‬ضــد ‪ ......‬واحملكــوم فيــه‬\n      ‫مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n\n\n‫‪289‬‬\n\f‫احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                         ‫‪290‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":286,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"902040fb63608d57f49b33212c12944562b48f10ac56d1655b3abffa0df6eb80","normalized_text_hash":"4e0f42eab1ac8f455d8882cba26e2e1a09677b6357481c887777926f57f3aa64","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p286-34309503"},{"id":"fd991337-ccdc-5835-9f25-ec40cee20c0b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -امتناع املدعى عليه عن دفع األجرة مقابل استخدام العقار- مطالبة املدعى عليه بسداد األجرة وإخاء العقار -تذرع املدعى عليه بعيب يف العقار -شهادة الشهود العدول -استخدام العقار اء بالعيب -اإللزام فترة طويلة دون املطالبة بفسخ العقد يعد رض بدفع مبلغ اإليجار وإخاء العقار .","document_number":"34259894","case_number":"303751122","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة احلقوقية الرابعة رقم 34341849 :يف1434/10/27 :ه ونص","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434 /7/4","year":"1434","subject":"إجارة -امتناع املدعى عليه عن دفع األجرة مقابل استخدام العقار- مطالبة املدعى عليه بسداد األجرة وإخاء العقار -تذرع املدعى عليه بعيب يف العقار -شهادة الشهود العدول -استخدام العقار اء بالعيب -اإللزام فترة طويلة دون املطالبة بفسخ العقد يعد رض بدفع مبلغ اإليجار وإخاء العقار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434 /7/4 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34259894 :‬‬\n                         ‫َر ْق ُم الدعوى‪303751122 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34341849‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬امتنــاع املدعــى عليــه عــن دفــع األجــرة مقابــل اســتخدام العقار‪-‬‬\n      ‫مطالبــة املدعــى عليــه بســداد األجــرة وإخــاء العقــار‪ -‬تــذرع املدعــى‬\n      ‫عليــه بعيــب يف العقــار‪ -‬شــهادة الشــهود العــدول‪ -‬اســتخدام العقــار‬\n      ‫ـاء بالعيــب‪ -‬اإللــزام‬\n                           ‫فتــرة طويلــة دون املطالبــة بفســخ العقــد يعــد رضـ ً‬\n                                          ‫بدفــع مبلــغ اإليجــار وإخــاء العقــار ‪.‬‬\n\n\n\n\n      ‫قــال ابــن تيميــه يف مختصــر الفتــاوى ‪( 412/1‬وتأخــر الدعــوى املمكنــة‬\n                    ‫يف مســائل اجلــور ونحوهــا يــدل علــى كــذب املدعــى بهــا)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أصالــة ووكالــة ضــد املدعــى عليــه بالوكالــة عــن‬\n      ‫صاحــب مؤسســة بــأن صاحــب املؤسســة قــد اســتأجر الــدور الثانــي مــن‬\n      ‫املجمــع التجــاري اململــوك للمدعــي وموكلــه ملــدة تســع ســنوات وقــرر‬\n      ‫املدعــي أصالــة ووكالــة أنــه بقــى مــن األجــرة لعــام ‪1432‬ه ـ مبلغـ ًا قــدره‬\n      ‫خمســة وعشــرون ألــف ريــال كمــا بقــي أجــرة الســنتني األخيرتــن مبلغـ ًا‬\n      ‫قــدره ســبعمائة وخمســون ألــف ريــال وطالــب املدعــي أصالــة ووكالــة‬\n      ‫بتســليم األجــرة احلالــة وإخــاء العقــار موطــن الدعــوى‪ ،‬صــادق املدعــى‬\n      ‫ا وذكــر أن ســبب عــدم‬      ‫عليــه وكالــة علــى الدعــوى جملــة وتفصي ـ ً‬\n\n‫‪291‬‬\n\f‫دفــع املبلــغ هــو أن املدعــي قــام بإزالــة مخــرج الطــوارئ خلــف العقــار‬\n‫محــل النــزاع وعــدم إصــاح مضخــات امليــاه للحرائــق وقــد تضــررت‬\n‫املؤسســة مــن جهــة تأخيــر اســتخراج تصاريــح الدفــاع املدنــي وفــات علــى‬\n‫املؤسســة التعاقــد يف مشــاريع تعليميــة واملؤسســة ملتزمــة باخلــروج يف‬\n‫‪1434/12/30‬ه ـ علمـ ًا بــأن املؤسســة مســتغلة للعقــار محــل النــزاع حتــى‬\n‫تاريخــه وتقيــم فيــه دورات لكنهــا لــم حتصــل علــى تصاريــح اجلهــات‬\n‫املختصة‪،‬احضــر املدعــي أصالــة ووكالــة شــاهدين مت تعديلهمــا شــرع ًا‬\n‫وشــهدا أن املؤسســة املدعــى عليهــا قــد اســتلمت العقــار محــل النــزاع‬\n‫بوضعــه احلالــي متامـ ًا وأن املؤسســة لهــا مخــرج طــوارئ خلــف املبنــى وأنــه‬\n‫لــم ينشــأ درج داخــل الســوبرماركت‪ ،‬قــرر ناظــر القضيــة أنــه بنــاء‬\n‫علــى مــا ســبق وأنــه علــى فــرض التســليم بــأن املدعــي قــام بإزالــة مخــرج‬\n‫الطــوارئ وأنــه لــم يقــم بإصالحــات مضخــات امليــاه للحرائــق فــإن تســليم‬\n‫املدعــى عليهــا ألجــرة عــام ‪1432‬ه ـ واســتخدام العقــار فتــرة طويلــة دون‬\n‫املطالبــة بفســخ العقــد يعــد رضــا بالعيــب كمــا أن دفــع املدعــى عليــه‬\n‫وكالــة بــأن درج الطــوارئ هــو الــذي داخــل الســوبر ماركــت غيــر وجيــه‬\n‫ألنــه يســتحيل أن يكــون مخــرج الطــوارئ داخــل محــل جتــاري كمــا أن‬\n‫الوكيــل ذكــر يف جوابــه علــى الدعــوى أن الــدرج خلــف املبنــى كمــا‬\n‫أن املدعــي وكالــة قــدم بينــة تؤيــد عــدم صحــة دفــع املدعــى عليــه لذلــك‬\n‫كلــه صــدر احلكــم علــى املدعــى عليهــا بتســليم املدعــي وموكلــه‬\n‫األجــرة احلالــة واحلكــم بإخــاء العقــار بتاريــخ ‪1434/12/30‬هــ‪ ،‬قــرر‬\n‫املدعــى عليــه وكالــة عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                                       ‫باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة‪ /‬املســاعد برقــم ‪303751122‬‬\n      ‫وتاريــخ ‪1431/12/16‬ه ـ املقيــدة باحملكمــة برقــم ‪31101226‬‬\n      ‫وتاريــخ ‪1431/12/16‬ه ـ وبعــد عــدة جلســات ففــي يــوم اإلثنــن املوافــق‪:‬‬\n      ‫‪1434/06/26‬ه ـ حضــر‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪ ........ :‬باألصالــة عــن نفســه وبالوكالــة عــن‪، ........ :‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجــدة رقــم‪........ :‬‬\n      ‫يف‪1431/6/18 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وحضــور‬\n      ‫اجللســات واســتالم احلقــوق مبوجــب شــيك باســم موكلــه والقناعــة‬\n      ‫باألحــكام واالعتــراض عليهــا وطلــب التحكيــم‪ .‬ا‪ .‬ه ـ وحضــر حلضوره‪:‬‬\n      ‫‪ ، ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ ........ :‬الوكيــل‬\n      ‫عــن‪ ........‬بصفتــه صاحــب مؤسســة ‪ ، ........‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بشــمال جــدة رقــم‪ ........ :‬يف‪1434/6/24 :‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وســماع الدعــوى والــرد عليهــا‬\n      ‫واإلقــرار واإلنــكار والصلــح والتنــازل‪ .‬ا‪ .‬ه ـ وادعــى األول قائــا‪ :‬إننــي‬\n      ‫أملــك أنــا وموكلــي عقــار يقــع طريــق األميــر ‪ ........‬ـ حــي ‪ ........‬وهــو‬\n      ‫عبــارة عــن مجمــع جتــاري واســمه (مركــز ‪ ،) ........‬وقــد اســتأجرت‬\n      ‫‪ ........‬الــدور الثانــي كامــا ملــدة تســع ســنوات اعتبــارا مــن تاريــخ‬\n      ‫‪1424/1/1‬ه وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ بأجــرة ســنوية للســنوات‬\n      ‫الثــاث األولــى وقدرهــا‪ :‬ثــاث مئــة وخمســة وعشــرون ألــف ريــال‪،‬‬\n\n‫‪293‬‬\n\f‫وللثــاث الســنوات الثانيــة بأجــرة ســنوية قدرهــا‪ :‬ثــاث مئــة وخمســون‬\n‫ألــف ريــال‪ ،‬وللثــاث الســنوات الثالثــة بأجــرة ســنوية قدرهــا‪ :‬ثــاث‬\n‫مئــة وخمســة وســبعون ألــف ريــال‪ ،‬وقــد التزمــت املؤسســة املدعــى‬\n‫عليهــا بدفــع األجــرة طيلــة الفتــرة الســابقة‪ ،‬وبقــي عليهــا مــن أجــرة عــام‬\n‫‪1432‬ه ـ مبلغــا قــدره‪ :‬واحــد وثالثــون الــف وثــاث مئــة وســبعة وخمســن‬\n‫ريــال لــم تســددها‪ ،‬كمــا أنهــا لــم تســدد أجــرة العقــار محــل النــزاع‬\n‫للســنتني‪1433 :‬ه ـ ‪1434‬ه ـ ‪ ،‬أطلــب إلــزام املؤسســة املدعــى عليهــا مبــا‬\n‫يلــي‪ ،‬أوال‪ :‬ســداد املبلــغ املتبقــي مــن أجــرة العقــار محــل النــزاع لعــام‪:‬‬\n‫‪1432‬ه ـ وقدرهــا‪ :‬واحــد وثالثــون الــف وثــاث مئــة وســبعة وخمســن‬\n‫ريــال‪ .‬ثانيــا‪ :‬ســداد أجــرة العقــار محــل النــزاع لعــام‪1433 :‬ه ـ وقدرهــا‪:‬‬\n‫ثــاث مئــة وخمســة وســبعون ألــف ريــال‪ .‬ثالثــا‪ :‬ســداد أجــرة العقــار محــل‬\n‫النــزاع لعــام‪1434 :‬ه ـ وقدرهــا‪ :‬ثــاث مئــة وخمســة وســبعون ألــف ريــال‪.‬‬\n‫رابعــا‪ :‬إخــاء العقــار محــل النــزاع بتاريــخ‪1434/12/30 :‬ه ـ ‪ ،‬هكــذا‬\n‫ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬أطلــب‬\n‫مهلــة لإلجابــة‪ ،‬هكــذا أجــاب‪ .‬ويف يــوم الثالثاء املوافــق ‪1434/6/27‬هـ‬\n‫حضــر املدعــي أصالــة ووكالــة‪ ، ........ :‬واملدعــى عليــه وكالــة‪........ :‬‬\n‫املثبــت حضورهمــا يف جلســة ســابقة‪ ،‬وبســؤال املدعى عليــه وكالة عما‬\n‫اســتمهل مــن أجلــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي أنــه ميلك هــو موكله‬\n‫العقــار الــذي يقــع طريــق األميــر ‪ ........‬ـ حــي ‪ ........‬وهــو عبــارة عــن مجمــع‬\n‫جتــاري واســمه (مركــز ‪ ) ........‬فصحيــح‪ ،‬ومــا ذكــره أن موكلتــي ـ‬\n‫مؤسســة ‪ ........‬ـ قــد اســتأجرت الــدور الثانــي كامــا ملــدة تســع ســنوات‬\n‫اعتبــارا مــن تاريــخ‪1424/1/1 :‬ه ـ وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ‬\n‫بأجــرة ســنوية للســنوات الثــاث األولــى وقدرهــا‪ :‬ثــاث مئــة وخمســة‬\n\n\n                                                                                           ‫‪294‬‬\n\f      ‫وعشــرون ألــف ريــال‪ ،‬وللثــاث الســنوات الثانيــة بأجــرة ســنوية قدرهــا‪:‬‬\n      ‫ثــاث مئــة وخمســون ألــف ريــال‪ ،‬وللثالث الســنوات الثالثة بأجرة ســنوية‬\n      ‫قدرهــا‪ :‬ثــاث مئــة وخمســة وســبعون ألــف ريــال فصحيــح‪ ،‬ومــا ذكــره‬\n      ‫أن موكلتــي قــد التزمــت بدفــع األجــرة طليلــة الفتــرة الســابقة‪ ،‬وبقــي‬\n      ‫عليهــا مــن أجــرة عــام ‪1432‬ه ـ مبلغــا قــدره‪ :‬واحــد وثالثــون ألــف وثــاث‬\n      ‫مئــة وســبعة وخمســن ريــال لــم تســددها فغيــر صحيــح‪ ،‬والصحيــح أنــه‬\n      ‫بقــي مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪ :‬خمســة وعشــرون ألــف ريــال‪،‬‬\n      ‫ومــا ذكــره أن موكلتــي لــم تســدد أجــرة العقــار محــل النــزاع للســنتني‪:‬‬\n      ‫‪1433‬ه ـ ‪1434‬ه ـ فصحيــح وهــي حالــة‪ ،‬وســبب امتنــاع موكلتــي مــن‬\n      ‫تســديد أجــرة الســنتني هــي أن املدعــي قــام بإزالــة مخــرج الطــوارئ‬\n      ‫الواقــع خلــف املبنــى مــن العقــار محــل النــزاع‪ ،‬وعــدم إصــاح مضخــات‬\n      ‫املــاء للحرائــق‪ ،‬وتضــررت موكلــي مــن جهــة تأخيــر اســتخراج تصاريــح‬\n      ‫الدفــاع املدنــي بســبب ذلــك‪ ،‬وقــد فــات علــى موكلتــي تعاقــد يف‬\n      ‫مشــاريع تعليميــة بجــدة حيــث إن العقــد يســتلزم رخصــة الدفــاع املدنــي‪،‬‬\n      ‫وموكلتــي ملتزمــة باخلــروج بتاريــخ‪1434/12/30 :‬ه ـ وأطلــب رد دعــوى‬\n                       ‫املدعــي وإخــاء ســبيل موكلتــي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــي أجــاب قائال‪ :‬ما ذكره املدعى عليه وكالة‬\n      ‫مــن جهــة التصاريــح وإزالــة مخــرج الطــوارئ فغيــر صحيــح‪ ،‬ومــا ذكــره‬\n      ‫أن املتبقــي خمســة وعشــرون ألــف ريــال فصحيــح‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه أجــاب قائــا‪ :‬ليــس لــدي بينــة‪ ،‬وأطلــب الوقــوف علــى‬\n      ‫العقــار محــل النــزاع لالطــاع عليــه‪ ،‬هكــذا أجــاب‪ .‬ثــم أضــاف املدعــي‬\n      ‫قائــا‪ :‬إن املدعــى عليــه وكالــة قصــده اللــدد وإطالــة أمــد الترافــع وهــذا‬\n      ‫ظاهــر مــن ســير الدعــوى‪ ،‬ولــدي البينــة علــى أن مخــرج الطــوارئ لــم‬\n\n\n‫‪295‬‬\n\f‫يــزال وهــو علــى حالــه‪ ،‬وأطلــب مهلــة إلحضارهــا‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن تاريــخ إزالــة املدعــي ملخــرج الطــوارئ‬\n‫أجــاب قائــا‪ :‬أطلــب مهلــة لإلجابــة‪ ،‬هكــذا أجــاب‪ .‬ويف يــوم األحــد‬\n‫املوافــق‪1434/07/02 :‬ه ـ حضــر املدعــي أصالــة ووكالــة‪،........ :‬‬\n‫وحضــر حلضــوره‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم‪ ........ :‬الوكيــل عــن‪ ........ :‬بصفتــه صاحــب مؤسســة ‪،........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة‬\n‫رقــم‪ ........ :‬يف‪1434/6/24 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫وســماع الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل‪.‬‬\n‫ا‪ .‬ه ـ وبســؤال املدعــى عليــه وكالــة عــن تاريــخ إزالــة املدعــي ملخــرج‬\n‫الطــوارئ أجــاب قائــا‪ :‬ال أذكــره بالتحديــد لكنــه أزال مضخــات‬\n‫احلرائــق ومخــارج الطــوارئ يف عــام‪1431 :‬ه ـ هكــذا أجــاب‪ .‬وبســؤاله‬\n‫عــن العقــار أجــاب قائــا‪ :‬موكلتــي مســتغلّة للعقــار محــل النــزاع حتــى‬\n‫تاريــخ اليــوم وتقيــم فيــه دورات لكــن لــم حتصــل علــى تراخيــص مــن‬\n‫املختصــة هكــذا أجــاب‪ .‬وبســؤال املدعــي أصالــة ووكالــة عمــا‬‫ّ‬        ‫اجلهــات‬\n‫اســتمهل مــن أجلــه أجــاب قائــا‪ :‬أطلــب مهلــة ثانيــة إلحضارهــا‪ ،‬هكذا‬\n‫أجــاب‪ .‬ويف يــوم الثالثــاء املوافــق‪1434/07/04 :‬هـ حضر املدعي أصالة‬\n‫ووكالــة‪ ، ........ :‬واملدعــى عليــه وكالــة‪ ، ........ :‬املثبــت حضورهمــا يف‬\n‫جلســة ســابقة‪ ،‬وبســؤال املدعــي أصالــة ووكالــة عمــا اســتمهل مــن أجله‬\n‫أحضــر للشــهادة وأدائهــا اثنــن؛ األول‪ ، ........ :‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم‪ ........ :‬وهــو مــن مواليــد عــام‪1410 :‬ه ـ ويســكن يف‬\n‫يف النــزاع‪ ،‬والثانــي‪:‬‬‫معقــب‪ ،‬وليــس لــه عالقــة بطــر ّ‬\n                                                        ‫حــي ‪ ، ........‬ويعمــل ّ‬\n‫‪ ، ........‬لبنانــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ........ :‬وهــو مــن‬\n\n\n                                                                                     ‫‪296‬‬\n\f      ‫مواليــد عــام‪1393 :‬ه ـ ويســكن يف حــي ‪ ، ........‬ويعمــل يف مؤسســة‬\n      ‫‪ ، ........‬وليــس لــه قرابــة بطــريف النــزاع‪ ،‬وبســؤالهما عمــا لديهمــا شــهد‬\n      ‫كل واحــد منهمــا قائــا‪( :‬أشــهد هلل أن املؤسســة املدعــى عليهــا قــد‬\n      ‫اســتلمت العقــار محــل النــزاع بنفــس وضعــه احلالــي متامــا‪ ،‬وأن املؤسســة‬\n      ‫املدعــى عليهــا لهــا مخــرج طــوارئ خلــف املبنــى)‪ ،‬هكــذا شــهدا‪.‬‬\n      ‫وعــدال مــن قبــل‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n      ‫رقــم‪ ........ :‬و‪ ، ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪:‬‬\n      ‫فشــهد كل واحــد منهمــا قائــا‪ :‬اشــهد هلل بعدالــة وثقــة الشــاهدين‪،‬‬\n      ‫هكــذا شــهدا‪ .‬وبعــرض الشــهود وشــهاداتهم علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب قائــا‪ :‬بالنســبة للشــهود فمســتوري احلــال‪ ،‬أمــا شــهادتهم‪ :‬فغيــر‬\n      ‫صحيحــة والصحيــح‪ :‬أن مدخــل الطــوارئ املذكــور ليــس هــو املقصــود‬\n      ‫لنــا‪ ،‬واملقصــود‪ :‬أن هنــاك مخــرج طــوارئ ينــزل مــن الــدور الثانــي الــذي‬\n      ‫اســتأجرته موكلتــي إلــى قلــب الــدور األرضــي وهــو بالتحديــد يف‬\n      ‫وســط (الســوبر ماركــت) وهــو مخــرج الطــوارئ املقصــود وقــد أزالــه‬\n      ‫املدعــي عــام‪1431 :‬هــ‪ ،‬وهــو الــذي طالــب بــه الدفــاع املدنــي‪ ،‬هكــذا‬\n      ‫أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬يســتحيل أن يكــون‬\n      ‫مخــرج الطــوارئ داخــل (الســوبر ماركــت)‪ ،‬ولــم ينشــأ أصــا درج يف‬\n      ‫وســط الســوبر ماركــت وألنــه ال خصوصيــة حينئــذ‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه أحضــر الشــهود املرصــودة أســماؤهم أعــاه فشــهدا‬\n      ‫قائلــن‪( :‬نشــهد هلل أن لــم ينشــأ أصــا درج داخــل الســوبر ماركــت)‪،‬‬\n      ‫القضيــة لهــذا احلـ ّـد فقــد قــررت قفــل‬\n                                            ‫ّ‬      ‫هكــذا شــهدا‪ .‬ونظــرا لوصــول‬\n      ‫القضيــة‪ .‬فبنــاء علــى مــا ســلف‪ ،‬وألن املدعــي‬\n                                                   ‫ّ‬     ‫بــاب املرافعــة‪ ،‬والبـ ّـت يف‬\n      ‫أصالــة ووكالــة طالــب مببلــغ قــدره‪ :‬واحــد وثالثــون ألــف وثــاث‬\n\n\n‫‪297‬‬\n\f‫مئــة وســبعة وخمســن ريــال وهــو جــزء متبقــي مــن أجــرة العقــار محــل‬\n‫النــزاع لعــام ‪1432‬ه ـ كمــا طالــب بأجــرة العقــار محــل النــزاع للســنتني‪:‬‬\n‫‪1433‬ه ـ ‪1434‬ه ـ وإخــاء العقــار بتاريــخ‪1434/12/30 :‬هــ‪ ،‬ومبــا أن‬\n‫املدعــى عليــه وكالــة صــادق أن موكلتــه قــد اســتأجرت العقــار محــل‬\n‫النــزاع مــن املدعــي ملــدة تســع ســنوات اعتبــارا مــن تاريــخ‪1424/1/1 :‬ه ـ‬\n‫وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ وأن أجــرة الســنوات مــن عام‪1432 :‬هـ‬\n‫و‪1433‬ه ـ و‪1434‬ه ـ كل ســنة قدرهــا‪ :‬ثــاث مئة وخمســة وســبعون ألف‬\n‫ريــال‪ ،‬وأنــه بقــي يف ذمــة موكلتــه مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪:‬‬\n‫خمســة وعشــرون ألــف ريــال‪ ،‬وأنهــا لــم تســدد أجــرة العقــار محــل النــزاع‬\n‫أحقية املدعي بأجرة الســنتني‬ ‫ّ‬     ‫للســنتني‪1433 :‬ه ـ ‪1434‬ه ـ ‪ ،‬ودفــع بعــدم‬\n‫ألجــل أنــه قــام بإزالــة مخــرج الطــوارئ الواقــع خلــف املبنــى مــن العقــار‬\n‫محــل النــزاع‪ ،‬وعــدم إصــاح مضخــات املــاء للحرائــق‪ ،‬وعلــى فــرض‬\n‫التســليم بــأن املدعــي قــام بإزالــة مخــرج الطــوارئ وأنــه لــم يقــم بإصــاح‬\n‫مضخــات املــاء للحرائــق أو أنــه أزالهــا فــإن تســليم املدعــى عليهــا للمدعي‬\n‫أجــرة عــام‪1432 :‬ه ـ بــل واســتخدامها للعقــار فتــرة طويلــة دون املطالبــة‬\n‫تيميــة ـ قـ ّـدس اهلل روحــه ـ‬\n                           ‫بفســخ العقــد يعـ ّـد رض ـ ًا بالعيــب‪ ،‬قــال ابــن ّ‬\n‫املصريــة ‪( : 412/1‬وتأخــر الدعــوى املمكنــة يف‬   ‫ّ‬       ‫يف مختصــر الفتــاوى‬\n‫مســائل اجلــور ونحوهــا يــدلّ علــى كــذب املدعــي بهــا)‪ .‬ا‪ .‬ه ـ كمــا أن‬\n‫دفــع املدعــى عليــه وكالــة بــأن درج الطــوارئ املقصــود هــو الــذي داخــل‬\n‫(الســوبر ماركــت) دفــع غيــر وجيــه‪ ،‬ألنــه يســتحيل أن يكــون مخــرج‬\n‫للطــوارئ داخــل محــل جتــاري‪ ،‬كمــا أن الوكيــل الســابق ذكــر يف‬\n‫جوابــه علــى الدعــوى أن الــدرج خلــف املبنــى‪ ،‬باإلضافة لذلــك أن املدعي‬\n‫صحــة دفعــه وهــي شــهادة الشــاهدين‬     ‫وكالــة قـ ّـدم ّبينــة تؤيــد عــدم ّ‬\n\n                                                                                     ‫‪298‬‬\n\f      ‫املرصــودة أعــاه‪ ،‬واملتضمنــة‪ :‬أن املؤسســة املدعــى عليهــا قــد اســتلمت‬\n      ‫العقــار محــل النــزاع بنفــس وضعــه احلالــي متامــا‪ ،‬وأن املؤسســة املدعــى‬\n      ‫عليهــا لهــا مخــرج طــوارئ خلــف املبنــى‪ .‬ا‪ .‬ه ـ وقــد جــرى تعديــل الشــهود‬\n      ‫ـرعية‪ ،‬ومبــا أن املدعــي صــادق‬ ‫القضيــة حســب األصــول الشـ ّ‬  ‫ّ‬        ‫يف ضبــط‬\n      ‫علــى أن املتبقــي مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪ :‬خمســة وعشــرون‬\n      ‫ألــف‪ ،‬ومبــا أن املدعــى عليــه وكالــة قــرر موافقتــه علــى إخــاء‬\n      ‫العقــار بتاريــخ‪1434/12/30 :‬ه ـ لذلــك كلــه فقــد ألزمــت املؤسســة‬\n      ‫املدعــى عليهــا (مؤسســة ‪ ) ........‬مبــا يلــي‪ ،‬أوال‪ :‬تســليم املبلــغ املتبقــي‬\n      ‫مــن أجــرة عــام‪1432 :‬ه ـ للمدعيــن‪ ، ........ :‬و‪ ........‬وقدرهــا‪ :‬خمســة‬\n      ‫وعشــرون ألــف ريــال‪ .‬ثاني ـاً‪ :‬تســليم أجــرة العقــار محــل النــزاع للســنتني‬\n      ‫‪1433‬ه ـ و‪1434‬ه ـ وإجمالــي قدرهــا‪ :‬ســبع مئــة وخمســون ألــف ريــال‬\n      ‫للمدعيــن‪ ، ........ :‬و‪ . ........‬ثالثــا‪ :‬إخــاء العقــار محــل النــزاع بتاريــخ‪:‬‬\n      ‫‪1434/12/30‬ه ـ وبذلــك قضيــت‪ .‬وبإعــان احلكــم عليهمــا قرر املدعي‬\n      ‫قناعتــه باحلكــم‪ ،‬وقــرر املدعــى عليــه وكالــة اعتراضــه واســتعد بتقــدمي‬\n      ‫اعتراضيــة‪ ،‬فجــرى تســليمه نســخة مــن احلكــم‪ ،‬وأفهــم بــأن‬     ‫ّ‬          ‫الئحــة‬\n      ‫لــه احلــق يف تقــدمي الئحتــه يف مــدة أقصاهــا ثالثــون يومــا اعتبــارا مــن‬\n      ‫تاريــخ هــذا اليــوم‪ ،‬وإذا انتهــت املــدة ولــم يقـ ّـدم الئحتــه ســقط حقــه يف‬\n      ‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/07/04 :‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االحــد املوافق ‪1434/11/09‬هـ افتتحت‬\n      ‫اجللســة ‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار‬\n      ‫الدائــرة احلقوقيــة الرابعــة رقــم‪ 34341849 :‬يف‪1434/10/27 :‬ه ـ ونــص‬\n      ‫احلاجــة منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n\n\n‫‪299‬‬\n\f‫تقــرر املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه وأمــرت‬\n‫بالتهميــش علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫ســيدنا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/9‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ........ /‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n‫‪34259894‬وتاريــخ ‪1434/7/4‬ه ـ املتضمــن دعــوى ‪( ........ ........‬أصالــة‬\n‫ووكالــة) ضــد مؤسســة ‪ ........‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق باملعاملــة‪ .‬وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":291,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7424f289d08ba2dd47116154e81e8e3b37e334724885711f85d4089cae4c294b","normalized_text_hash":"18a54452714db34ad8e9344b41882211f4eb509e66a9af390cbf64ddfd90ffc7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p291-34259894"},{"id":"f4b4c907-c282-5a0e-9033-e6bd8e379875","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتبلغ املدعى عليه لشخصه -إثبات الطلب مبوجب سند ألمر ومين االستظهار -تخلف املدعى عليه عن احلضور يعد نكو ال عن اجلواب -احلكم بدفع أجرة العن.","document_number":"34303751","case_number":"34268795","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة اجلزائية بالطائف واملسجل بعدد 34303751 و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"إجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتبلغ املدعى عليه لشخصه -إثبات الطلب مبوجب سند ألمر ومين االستظهار -تخلف املدعى عليه عن احلضور يعد نكو ال عن اجلواب -احلكم بدفع أجرة العن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/23 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34303751 :‬‬\n                          ‫َر ْق ُم الدعوى‪34268795 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 35112651‬تاريخه‪1435/1/11:‬هـ‬\n\n\n      ‫إجــارة ‪ -‬مطالبــة بأجــرة عــن ‪ -‬ســماع الدعــوى غيابي ـ ًا لتبلــغ املدعــى‬\n      ‫عليــه لشــخصه ‪ -‬إثبــات الطلــب مبوجــب ســند ألمــر وميــن االســتظهار‬\n      ‫‪ -‬تخلــف املدعــى عليــه عــن احلضــور يعــد نكــو ًال عــن اجلــواب ‪ -‬احلكــم‬\n                                                                 ‫بدفــع أجــرة العــن‪.‬‬\n\n\n\n\n                                     ‫‪ .1‬املادة رقم ‪ 1/55‬من نظام املرافعات الشرعية‪.‬‬\n                                        ‫‪ .2‬املادة ‪ 4/176‬من نظام املرافعات الشرعية‪.‬‬\n                                           ‫‪ .3‬املادة ‪ 178‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n      ‫اســتأجر منــه شــقة ملــدة ســنتني بأجــرة ســنوية قدرهــا أربعــة عشــر ألــف‬\n      ‫ريــال ســدد منهــا املدعــى عليــه مبلغـ ًا وقــدره أحــد عشــر ألفـ ًا وثالثمائــة‬\n      ‫ريــال وتبقــى عليــه يف ذمتــه مبلــغ حــال قــدره ســتة عشــر ألفـ ًا وســبعمائة‬\n      ‫ريــال ويطلــب بإلزامــه بســداد املبلــغ املدعــى بــه حــا ًال ‪ ،‬ســمعت الدعــوى‬\n      ‫لغيــاب املدعــى عليــه لتبلغــه لشــخصه‪ ،‬اســتناد ًا للمــادة ‪ 55‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحهــا التنفيذيــة‪ ،‬بينــة املدعــي ســند ألمــر‬\n      ‫يتضمــن وفــق مــا جــاء يف الدعــوى‪ ،‬حلــف املدعــي ميــن االســتظهار‬\n\n‫‪301‬‬\n\f‫علــى صحــة دعــواه بعــد طلبهــا منــه‪ ،‬ومبــا أن تخلــف املدعــى عليــه عــن‬\n‫احلضــور مــع تبلغــه يعــد نكــو ًال عــن اجلــواب‪ ،‬وألن املدعــي حلــف اليمــن‬\n‫علــى دعــواه ونفــي اســتالمه املبلــغ املدعــى بــه‪ ،‬صــدر احلكــم علــى‬\n‫املدعــى عليــه بدفــع املبلــغ‪ ،‬احلكــم يف حــق املدعــى عليــه حضــوري‪،‬‬\n‫اســتناد ًا للمــادة‪ 1/55‬مــن نظــام املرافعــات الشــرعية والئحتــه‪ ،‬قنــع‬\n‫املدعــي باحلكــم‪ ،‬تبليــغ املدعــى عليــه باحلكــم اســتناد ًا للمــادة ‪4/176‬‬\n‫مــن نظــام املرافعــات الشــرعية والئحتــه‪ ،‬صــدق احلكــم مــن الدائــرة‬\n    ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالطائــف برقــم ‪ 34268795‬وتاريــخ ‪ 1434/06/12‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341413524‬وتاريــخ ‪ 1434/06/12‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/08/23‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة وفيهــا حضــر املدعــي ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه‪ .....‬وال مــن ينــوب عنــه ولــم‬\n‫يتقــدم بعــذر لتخلفــه عــن املوعــد وقــد وردتنــا إفــادة محضــري اخلصــوم‬\n‫برقــم (‪ )846‬يف ‪1434/7/2‬ه ـ املتضمنــة ( أنــه مت إبــاغ املدعــى عليــه‬\n‫شــخصيا مبوعــد اجللســة ووقــع علــى ذلــك ) وبنــاء علــى املــادة ‪ 55‬مــن‬\n‫نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة قــررت ســماع هــذه‬\n‫الدعــوى بغيــاب املدعــى عليــه فســألت املدعــي عــن دعــواه فادعــى ضــد‬\n‫الغائــب عــن مجلــس احلكــم قائــا يف حتريــر دعــواه لقــد أجــرت املدعــى‬\n\n                                                                                     ‫‪302‬‬\n\f      ‫عليــه شــقة يف عمارتــي بتاريــخ ‪1432/6/20‬ه ـ ملــدة ســنتني بأجــرة‬\n      ‫ســنوية قدرهــا ( ‪ ) 14000‬أربعــة عشــر ألــف ريــال وســدد لــي مــن ذلــك‬\n      ‫(‪ )11300‬إحــدى عشــر ألفــا وثالثمائــة ريــال وبقــي لــي يف ذمتــه مبلــغ‬\n      ‫حــال قــدره (‪ )16700‬ســتة عشــر ألفــا وســبعمائة ريــال أطلــب إلزامــه‬\n      ‫بدفــع املبلــغ املتبقــي لــي يف ذمتــه حــاال هــذه دعــواي فطلبــت مــن املدعــي‬\n      ‫البينــة علــى دعــواه فأبــرز ســندا ألمــر صــادرة مــن محافظــة الطائــف‬\n      ‫برقــم (‪ )1‬يف ‪1434/6/4‬ه ـ ويتضمــن وفــق ماجــاء يف الدعــوى وعليــه‬\n      ‫توقيــع ذكــر املدعــي أنــه يعــود للمدعــى عليــه وقــد جــرى إرفــاق صــورة‬\n      ‫منــه باملعاملــة فطلبــت مــن املدعــي ميــن االســتظهار علــى دعــواه و أن‬\n      ‫املبلــغ الــذي يطالــب بــه حــال يف ذمــة املدعــى عليــه ولــم يدفعــه لــه حتــى‬\n      ‫اآلن ‪ ،‬فاســتعد بذلــك بعــد تذكيــره بعظــم اليمــن الغمــوس وخطورتهــا‬\n      ‫ثــم حلــف قائــا ( واهلل العظيــم الــذي ال إلــه إال هــو أننــي أجــرت املدعــى‬\n      ‫عليــه شــقة يف عمارتــي الواقعــة بحــي ‪ ......‬ملــدة ســنتني بأجــرة ســنوية‬\n      ‫قدرهــا مببلــغ قــدره ( ‪ )14000‬أربعــة عشــر ألــف ريــال وبقــي لــي يف ذمتــه‬\n      ‫مــن أجــرة الســنتني (‪ )16700‬ســتة عشــر ألفــا وســبعمائة ريــال وهــو حــال‬\n      ‫يف ذمتــه ولــم يدفــع لــي هــذا املبلــغ حتــى االن) هكــذا حلــف فبعــد‬\n      ‫ســماعي للدعــوى واالطــاع علــى أوراق املعاملــة‪ ،‬وألن املدعــي حلــف‬\n      ‫ميــن االســتظهار علــى دعــواه و نفــي اســتالمه للمبلــغ الــذي يطالــب بــه‬\n      ‫وألن املدعــى عليــه قــد تب َّلــغ شــخصيا مبوعــد هــذه اجللســة ولــم يحضــر‬\n      ‫وألن تخلفــه عــن موعــد هــذه اجللســة يعــد نكــوال عــن اجلــواب والنــاكل‬\n      ‫يقضــى عليــه بالنكــول ‪ ،‬وحيــث نصــت املــادة رقــم ‪ 1/55‬مــن نظــام‬\n      ‫املرافعــات علــى أنــه إذا تبلــغ املدعــى عليــه شــخصيا مبوعــد اجللســة ولــم‬\n      ‫ـواء كان غيابــه قبــل قفــل‬ ‫يحضــر فيعــد احلكــم يف حقــه حضوري ـ ًا سـ ً‬\n\n‫‪303‬‬\n\f‫بــاب املرافعــة ‪ ،‬أم بعــده ‪ ، ،‬لهــذا كلــه فقــد حكمــت علــى املدعــى‬\n‫عليــه أن يدفــع للمدعــي املبلــغ املدعــى بــه حــاال وقــدره (‪ )16700‬ســتة‬\n‫عشــر ألفــا وســبعمائة ريــال ‪ ،‬وبعرضــه علــى املدعــي قــرر قناعتــه بــه ‪،‬‬\n‫وقــررت بعــث نســخة مــن صــك احلكــم للمدعــى عليــه لتقــدمي الئحتــه‬\n‫االعتراضيــة إذا لــم يقتنــع باحلكــم خــال املــدة املقــررة نظام ـ ًا وهــي‬\n‫ثالثــون يوم ـ ًا مــن تاريــخ التبليــغ حســب املــادة ‪ 4/176‬مــن الالئحــة‬\n‫التنفيذيــة لنظــام املرافعــات الشــرعية ‪ ،‬وإذا مضــت مــدة االعتــراض ولــم‬\n‫يقــدم اعتراضــه ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫حســب املــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية ‪ ،‬كمــا أن احلكــم‬\n‫يعــد حضوري ـ ًا يف حــق املدعــى عليــه حســب املــادة ‪ 1/55‬مــن الالئحــة‬\n‫التنفيذيــة لنظــام املرافعــات الشــرعية وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/23‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثالثــة مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالطائــف برقــم ‪34/1413524‬‬\n‫وتاريــخ ‪1435/01/01‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪.....‬باحملكمــة العامــة اجلزائيــة بالطائــف واملســجل بعــدد ‪34303751‬‬\n‫وتاريــخ ‪1434/08/23‬هـ ـ واملتضمــن دعــوى ‪ .....‬ضــد ‪.....‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه تقــرر املوافقــة علــى‬\n‫احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n                                                                                    ‫‪304‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":301,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8b7543e449961737aca999f040fe9714492a05b5f93c39293c6e0895c196baa9","normalized_text_hash":"2bf6cdd64761ba122be00c416e0a6d671dc2edbf9e367075ffd06b9605b1708d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p301-34303751"},{"id":"427c895f-387c-58d5-9b23-32ca1943fff0","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء العقار باألخطار كطلب اصلي وإلزام بأجرة يوميه كطلب عارض -حصول تفريط موجب للخسارة من قبل املدعى عليه -احلكم باإلخاء يف الطلب األصل واستبقاء الطلب العارض حتى توفر مسوغات البت فيه .","document_number":"34276464","case_number":"3452496","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"إجارة -إخاء العقار باألخطار كطلب اصلي وإلزام بأجرة يوميه كطلب عارض -حصول تفريط موجب للخسارة من قبل املدعى عليه -احلكم باإلخاء يف الطلب األصل واستبقاء الطلب العارض حتى توفر مسوغات البت فيه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/23 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34276464 :‬‬\n                          ‫َر ْق ُم الدعوى‪3452496 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34297417‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬إخــاء العقــار باألخطــار كطلــب اصلــي وإلــزام بأجــرة يوميــه‬\n      ‫كطلــب عــارض ‪ -‬حصــول تفريــط موجــب للخســارة مــن قبــل املدعــى‬\n      ‫عليــه ‪ -‬احلكــم باإلخــاء يف الطلــب األصــل واســتبقاء الطلــب العــارض‬\n                                           ‫حتــى توفــر مســوغات البــت فيــه ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى «يــا أيهــا الذيــن امنــوا ال تأكلــوا أموالكــم بينكــم‬\n                           ‫بالباطــل إال أن تكــون جتــارة عــن تــراض منكــم»‬\n                       ‫‪ -2‬قوله صلى اهلل عليه وسلم «إمنا البيع عن تراض»‪.‬‬\n      ‫‪ -3‬قــال املــرداوي رحمــه اهلل «وظيفــة الناظــر ‪ :‬حفــظ الوقــف والعمــارة‬\n      ‫واإليجــار والزراعــة واملخاصمــة فيــه وحتصيــل ريعــه من تأجيــره أو زرعه‬\n      ‫أو ثمــره واالجتهــاد يف تنميتــه وصرفــه يف جهاتــه مــن عمــارة وإصــاح‬\n                             ‫وإعطــاء مســتحقة ونحــو ذلــك» اإلنصــاف ‪68/7‬‬\n                                  ‫‪ -4‬املادة (‪ )81‬من نظام املرافعات الشرعية ‪.‬‬\n                                              ‫‪ -5‬املادة (‪ )72‬من نظام التنفيذ ‪.‬‬\n\n\n\n\n‫‪305‬‬\n\f‫ادعــى منــدوب إدارة األوقــاف واملســاجد مبكــة املكرمــة مبوجــب‬\n‫خطــاب تفويــض ضــد املدعــى عليــه أن املدعــى عليــه قــد اســتأجر مــن‬\n‫ا مــن عمــارة وقــف‬   ‫إدارة األوقــاف واملســاجد مبكــة املكرمــة مح ـ ً‬\n‫مســجد ‪ ...‬مبوجــب عقــد محــرر ملــدة ســنة قابلــة للتجديــد مــا لــم يخطــر‬\n‫احــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب مســجل قبــل نهايتــه‬\n‫بشــهرين وقــد جتــدد العقــد ألربعــة أعــوام ومت أبالغــه بعــدم الرغبــة يف‬\n‫جتديــد العقــد يف نهايــة الســنة األخيــرة بخطــاب اإلدارة املوجــه لصنــدوق‬\n‫بريــد املدعــى عليــه ورفــض املدعــى عليــه تســليم احملــل لــإدارة وطلــب‬\n‫املدعــى احلكــم علــى املدعــى عليــه بإخــاء العقــار وتســليمه لــإدارة بعــد‬\n‫تصفيــة الكهربــاء وهــذا هــو الطلــب األصلــي وثانيــا إلــزام املدعــى عليــه‬\n‫بدفــع أجــرة يوميــة للعقــار مــن تاريــخ ‪ 1434/1/1‬ه ـ وحتــى تاريــخ تســليم‬\n‫العقــار لــإدارة ‪ ،‬أجــاب املدعــى عليــه باملصادقة على العقد واالســتئجار‬\n‫واملــدة ومقــدار األجــرة وانكــر تلقيــه خطــاب عــدم التجديــد مــن اإلدارة‬\n‫املدعيــة‪ ،‬مت طلــب البينــة مــن املدعــى فأجــاب بــان اإلدارة بعثــت بخطــاب‬\n‫للمدعــى عليــه علــى صنــدوق بريــده املشــار إليــه يف العقــد وقــد مت‬\n‫اســتالمه مــن قبــل البريــد الرســمي مبوجــب كشــف التســليم املرفــق‬\n‫باملعاملــة‪ ،‬تلقــى ناظــر القضيــة خطابــا مــن البريــد يفيــد أن إرســالية‬\n‫إدارة األوقــاف ثــم إيداعهــا يف صنــدوق بريــد املدعــى عليــه ومكثــت ملدة‬\n‫شــهر ولــم يراجــع املدعــى عليــه الســتالمها فتــم تســليمها ملنــدوب إدارة‬\n‫األوقــاف حســب املتبــع‪ ،‬مت الرجــوع إلــى العقــد بــن الطرفــن فوجــد أن‬\n‫بيانــات املدعــى عليــه قــد ســجلت يف الصفحــة األولــى وتتضمــن اســمه‬\n\n                                                                                   ‫‪306‬‬\n\f      ‫ورقــم هويتــه ورقــم هاتفــه وصنــدوق بريده‪،‬وصــادق علــى ذلــك املدعــى‬\n      ‫عليــه‪ ،‬بنــاء علــى مــا تقــدم وحيــث تبــن أن خطــاب طلــب اإلخــاء قــد‬\n      ‫مت إيداعــه يف صنــدوق بريــد املدعــى عليــه والــذي جعلــه مبوجــب العقــد‬\n      ‫عنوانـ ًا مختــار ًا مــن قبلــه وعــدم اســتالمه مــع ثبــوت إيداعــه يف الصنــدوق‬\n      ‫غيــر وجيــه ألنــه لــو صــح فإنــه تفريــط مــن املدعــى عليــه يوجــب خلســارته‬\n      ‫ولــم يثبــت تفريــط اإلدارة املدعيــة ولذلــك وملــا جــاء يف املــادة ‪ 81‬مــن نظام‬\n      ‫املرافعــات الشــرعية وحيــث توفــرت مســوغات البــت يف الطلــب األصلــي‬\n      ‫ومراعــاة لســرعة البــت يف القضيــة فقــد صــدر احلكــم بإلــزام املدعــى‬\n      ‫عليــه بإخــاء احملــل موطــن الدعــوى حــا ًال وتســليمه لــإدارة املدعيــة وفى‬\n      ‫حــال امتنــاع املدعــى عليــه أو تغيبــه فينفــذ احلكــم وفــق املــادة (‪ )72‬مــن‬\n      ‫نظــام التنفيــذ املنظمــة لذلــك‪ ،‬واســتبقاء احلكــم بإلــزام املدعــى عليــه‬\n      ‫باألجــرة حلــن توفــر مســوغات البــت فيــه‪ ،‬قنــع ممثــل اإلدارة املدعيــة‬\n      ‫باحلكــم‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n            ‫االســتئناف مبكــة املكرمــة باملوافقــة علــى احلكــم باألكثريــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فلــدي‬\n      ‫أنــا القاضــي باحملكمــة العامــة مبكــة املكرمــة بنــاء علــى املعاملــة‬\n      ‫احملالــة إلينــا مــن فضيلــة الرئيــس برقــم ‪ 3452496‬يف ‪1434/02/02‬ه ـ‬\n      ‫واملقيــدة بهــذه احملكمــة برقــم ‪ 34260098‬وتاريــخ ‪1434/02/02‬ه ـ‬\n      ‫ففــي هــذا اليــوم األحــد املوافــق ‪1434/03/15‬ه ـ افتتحت اجللســة يف متام‬\n      ‫الســاعة التاســعة صباح ـ ًا وفيهــا حضــر ســعودي بالســجل املدنــي رقــم‬\n      ‫بصفتــه منــدوب األوقــاف واملســاجد مبكــة املكرمــة مبوجــب خطــاب‬\n\n‫‪307‬‬\n\f‫التفويــض رقــم ‪ 11/1607‬يف ‪1429/05/09‬ه ـ وادعــى ضــد ســعودي‬\n‫ا يف تقريــر دعــواه ضــده ‪ :‬إن املدعــى عليــه‬        ‫بالســجل املدنــي رقــم قائ ـ ً‬\n‫اســتأجر مــن إدارة األوقــاف مبكــة املكرمــة احملــل رقــم (‪ )2‬مــن عمــارة‬\n‫وقــف مســجد ‪ ...‬مبوجــب عقــد محــرر بينهمــا مــؤرخ يف ‪1429/03/07‬ه ـ‬\n‫ملــدة ســنة ابتــداء مــن ‪1429/01/01‬ه ـ قابلــة للتجديــد ملــدة أخــرى مالــم‬\n‫يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب مســتقل‬\n‫بأجــرة ســنوية قدرهــا خمســة عشــر ألــف ريــال وقــد جتــدد العقــد معــه‬\n‫لألعــوام التاليــة ‪ 1430‬و ‪1431‬ه ـ و‪1432‬ه ـ و‪1433‬ه ــوأبلغ بعــدم الرغبة‬\n‫يف جتديــد العقــد الــذي ينتهــي يف نهايــة ‪1433‬ه ـ بخطــاب االدارة رقــم‬\n‫‪ 6/3241‬يف ‪1433/10/21‬ه ـ ورفــض املدعــى عليــه تســليم الــدكان‬\n‫حتــى تاريخــه لــذا ؛ أطلــب مــا يلــي ‪ :‬أو ًال ‪ :‬احلكــم علــى املدعــى عليــه‬\n‫بإخــاء العقــار وتســليمه إلدارة األوقــاف مبكــة املكرمــة بعــد تصفيــة‬\n‫الكهربــاء وهــو طلبــي األصلــي ‪ .‬ثانيـ ًا ‪ :‬إلــزام املدعــى عليــه بدفــع أجــرة‬\n‫يوميــة للعقــار مقدارهــا (‪139‬ريــال ) مائــة وتســعة وثالثــون ريــال مــن‬\n‫‪1434/01/01‬ه ـ وحتــى تســليم العقــار هــذه دعــواي وبعــرض الدعــوى‬\n‫علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن‬\n‫ناحيــة العقــد واالســتئجار والعقــد واملــدة ومقــدار األجــرة فصحيــح ومــا‬\n‫ذكــره مــن إبالغــي بعــدم التجديــد يف ‪1433/10/21‬ه ـ فغيــر صحيــح‬\n‫فلــم يصلنــي مــن إدارة األوقــاف مــا يفيــد ذلــك وأطلــب رد دعــواه نظــر ًا‬\n‫لســريان العقــد وجتــدده لعــام ‪1434‬ه ـ هكــذا أجــاب وبســؤال املدعــي‬\n‫عــن البينــة علــى دعــواه أجــاب ‪ :‬بــأن االدارة قــد بعثــت خطاب ـ ًا للمدعــى‬\n‫عليــه برقــم ‪ 6/3241‬يف ‪1433/10/21‬ه ـ وقــد اســتلم مــن قبــل البريــد‬\n‫الرســمي يف ‪1433/10/22‬هـ مبوجب كشــف التســليم املرفق باملعاملة‬\n\n\n                                                                                         ‫‪308‬‬\n\f      ‫علــى صنــدوق بريــد املدعــى عليــه رقــم ‪ ....‬مكــة هكــذا أجــاب وبســؤال‬\n      ‫املدعــى عليــه عــن رقــم صنــدوق بريــده أجــاب بــأن رقــم صنــدوق بريــده‬\n      ‫هــو ‪ ....‬مكــة هكــذا أجــاب عنــد ذلــك طلبــت مــن املدعــي العقــد فأبــرز‬\n      ‫العقــد املوقــع مــن قبــل املدعــى عليــه يف ‪1429/03/07‬ه ـ وباالطــاع‬\n      ‫عليــه وجــد أنــه يتضمــن تأجيــر وزارة األوقــاف املدعــى عليــه الــدكان‬\n      ‫رقــم (‪ )2‬مــن وقــف مســجد ‪ ...‬بأجــرة ســنوية مقدارهــا خمســة عشــر ألــف‬\n      ‫ريــال وقــد نصــت الفقــرة األولــى مــن املــادة الثانيــة من العقد علــى ‪(( :‬مدة‬\n      ‫اإليجــار ســنة تبــدأ مــن ‪1429/01/01‬ه ـ وهــذه املــدة قابلــة للتجديــد ملدد‬\n      ‫أخــرى مالــم يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب‬\n      ‫مســجل قبــل شــهرين علــى األقــل مــن تاريــخ انتهــاء مــدة العقــد )) وحيــث‬\n      ‫األمــر مــا ذكــر فقــد قــررت الكتابــة للبريــد الســعودي مبكــة‬\n      ‫املكرمــة لإلفــادة عــن اإلرســالية ومــا مت بشــأنها ثــم يف يــوم الســبت‬\n      ‫املوافــق ‪1434/07/15‬ه ـ افتتحــت اجللســة لــدى فضيلــة القائــم بعملــي‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة يف متــام الســاعة التاســعة‬\n      ‫والنصــف صباح ـ ًا وقــد وردنــا اجلــواب علــى خطابنــا رقــم ‪34728059‬‬\n      ‫وتاريــخ ‪1434/03/23‬ه ـ مبوجــب خطــاب مديــر البريــد الرســمي‬\n      ‫بالعاصمــة املقدســة رقــم ‪/121‬ر وتاريــخ ‪1434/03/28‬ه ـ املقيــد‬\n      ‫بهــذه احملكمــة برقــم ‪ 34803141‬وتاريــخ ‪1434/04/02‬ه ـ املتضمــن‬\n      ‫((نفيدكــم بــأن اخلطــاب مت إيداعــه يف صنــدوق املذكــور مــن تاريــخ‬\n      ‫‪1433/10/28‬ه ـ إلــى ‪1433/11/29‬ه ـ وحســب مــا هــو متبــع مكــوث‬\n      ‫املــادة يف الصنــدوق ملــدة شــهر حيــث إن املذكــور لــم يقــوم مبراجعــة‬\n      ‫صندوقــه خــال هــذه الفتــرة ومــن ذلــك مت تســليمها إلــى منــدوب فــرع‬\n      ‫وزارة الشــؤون اإلســامية واألوقــاف مبكــة بتاريــخ ‪1433/12/01‬هــ))‬\n\n\n‫‪309‬‬\n\f‫ثــم يف يــوم األحــد املوافــق ‪1434/07/23‬ه ـ افتتحــت اجللســة يف متــام‬\n‫الســاعة التاســعة صباحـ ًا وفيهــا حضــر الطرفــان وبالرجــوع للعقــد املنــوه‬\n‫عنــه بعاليــه وجــد أن بيانــات املدعــى عليــه قد ســجلت يف الصفحة األولى‬\n‫ا ورقــم هويتــه ورقــم هاتفــه وعنــوان‬    ‫مــن العقــد وتتضمــن اســمه كام ـ ً‬\n‫صنــدوق بريــده وهــو (‪ )...‬مكــة‪ ،‬وصــادق علــى ذلــك املدعــى عليــه‪.‬‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طلــب جهــة اإلدارة‬    ‫فبنـ ً‬\n‫املدعيــة إلــزام املدعــى عليــه بإخــاء العقــار املوصــوف يف الدعــوى ودفــع‬\n‫األجــرة ‪ ،‬وبعــد االطــاع علــى العقــد والــذي صــادق عليــه املدعــى عليــه‬\n‫واملتضمــن يف الفقــرة األولــى مــن املــادة الثانيــة مــن العقــد أنــه ((مــدة‬\n‫اإليجــار ســنة تبــدأ مــن ‪1429/01/01‬ه ـ وهــذه املــدة قابلــة للتجديــد ملدد‬\n‫أخــرى مالــم يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب‬\n‫مســجل قبــل شــهرين علــى األقــل مــن تاريــخ انتهــاء مــدة العقــد)) وحيــث‬\n‫تبــن أن خطــاب طلــب اإلخــاء قــد أودع بتاريــخ ‪1433/10/28‬ه ـ يف‬\n‫صنــدوق بريــد املدعــى عليــه والــذي جعلــه مبوجــب العقــد عنوانـ ًا مختــار ًا‬\n‫مــن قبلــه ‪ ،‬لتلقــي اإلخطــارات فيــه وذلــك حســب خطــاب مديــر البريــد‬\n‫الرســمي بالعاصمــة املقدســة رقــم ‪/121‬ر وتاريــخ ‪1434/03/28‬ه ـ‬\n‫املقيــد بهــذه احملكمــة برقــم ‪ 34803141‬وتاريــخ ‪1434/04/02‬هــ‪،‬‬\n‫املرصــود مضمونــه بعاليــه‪ ،‬وحيــث إن مــا دفــع بــه املدعــى عليــه مــن عــدم‬\n‫اســتالمه للخطــاب مــع ثبــوت إيداعــه يف صنــدوق بريــده غيــر متوجــه؛‬\n‫ألنــه لــو صــح فإنــه تفريــط منــه موجــب خلســارته‪ ،‬ســيما والثابــت مــن‬\n‫األوراق عــدم تفريــط اجلهــة املدعيــة بإبــاغ املدعــى عليــه علــى عنوانــه‬\n‫املختــار بعــدم الرغبــة يف التجديــد لســنة أخــرى إنفــاذ ًا ملقتضيــات العقــد‬\n‫احملــرر بــن املتداعيــن‪ ،‬وحيــث أن اجلهــة املدعيــة لهــا حــق التصــرف‬\n\n\n                                                                                      ‫‪310‬‬\n\f      ‫باملنفعــة باألحــظ جلهــة الوقــف باعتبارهــا ناظــرة علــى األوقــاف اخليريــة‬\n      ‫مبكــة‪ ،‬والتأجيــر وتنميــة الوقــف مــن وظيفــة الناظــر‪ ،‬قــال املــرداوي‬\n      ‫‪-‬رحمــه اهلل‪(( :-‬وظيفــة الناظــر‪ :‬حفــظ الوقــف والعمــارة‪ ،‬واإليجــار‬\n      ‫والزراعــة واملخاصمــة فيــه‪ ،‬وحتصيــل ريعــه مــن تأجيــره أو زرعــه أو‬\n      ‫ثمــره‪ ،‬واالجتهــاد يف تنميتــه‪ ،‬وصرفــه يف جهاتــه مــن عمــارة وإصــاح‪،‬‬\n      ‫وإعطــاء مســتحقه ونحــو ذلــك)) [اإلنصــاف ‪ ،]68/7‬واألصــل إطــاق‬\n      ‫تصرفهــا يف منفعتــه‪ ،‬وقــد رغبــت اإلخــاء حتقيق ـ ًا ملصلحــة الوقــف‬\n      ‫واحلــق ال يعدوهــا‪ ،‬ولكــون أحــظ أركان العقــود هــو الرضــا لقولــه‬\n      ‫تعالــى ‪ (( :‬ياأيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل إال‬\n      ‫ـراض منكــم )) وقولــه صلــى اهلل عليــه وســلم ‪:‬‬  ‫أن تكــون جتــارة عــن تـ ٍ‬\n      ‫(( إمنــا البيــع عــن تــراض ))‪ ،‬واســتناد ًا للمــادة (‪ )81‬مــن نظــام املرافعــات‬\n      ‫الشــرعية التــي نصــت علــى أنه ((حتكم احملكمــة يف موضوع الطلبات‬\n      ‫العارضــة مــع الدعــوى األصليــة كلمــا أمكــن ذلــك ‪ ،‬وإال اســتبقت‬\n      ‫الطلــب العــارض للحكــم فيــه بعــد حتقيقــه)) وحيــث توفــر مســوغات‬\n      ‫البــت يف الطلــب األصلــي املقــدم مــن اجلهــة املدعيــة‪ ،‬ومراعــاة لســرعة‬\n      ‫البــت يف القضيــة ‪ ،‬فلمــا ســبق كلــه فقــد قــررت يلــي ‪ :‬أوالً‪ :‬حكمــت‬\n      ‫بإلــزام املدعــى عليــه بإخــاء احملــل رقــم (‪ )2‬مــن عمــارة وقــف مســجد‬\n      ‫‪ ....‬موضــع الدعــوى حــاالً‪ ،‬وتســليمه إلدارة األوقــاف مبكــة املكرمــة‪،‬‬\n      ‫ويف حالــة امتناعــه أو تغيبــه فينفــذ احلكــم طبقـ ًا للمــادة (‪ )72‬مــن نظــام‬\n      ‫التنفيــذ املنظمــة لذلــك‪ .‬ثانيـاً‪ :‬قــررت اســتبقاء احلكــم يف طلــب املدعيــة‬\n      ‫إدارة األوقــاف الثانــي وهــو إلــزام املدعــى عليــه بأجــرة احملــل حلــن توفــر‬\n      ‫مســوغات البــت فيــه‪ .‬هــذا مــا حكمــت بــه وبإعــان احلكــم قــرر ممثــل‬\n      ‫اجلهــة املدعيــة قناعتــه باحلكــم‪ ،‬وقــرر املدعــى عليــه عدمهــا وطلــب‬\n\n\n‫‪311‬‬\n\f‫اســتئنافه بالئحــة فجــرى تســليمه بنســخه مــن الصــك يف نفــس اليــوم‬\n‫وإفهامــه بــأن مــدة االعتــراض ثالثــون يومـ ًا اعتبــار ًا مــن تاريــخ هــذا اليــوم‬\n‫وبأنــه إذا لــم يتقــدم بالئحــة اعتراضيــة خاللهــا فــإن حقــه يف االعتــراض‬\n‫يســقط ويكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                         ‫نبينــا محمــد آلــه وســلم حــرر يف ‪1434/07/23‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االربعــاء املوافــق ‪1434/09/16‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 34260098‬وتاريــخ ‪1434/08/30‬ه ـ واملقيــدة بأســاس هــذه احملكمــة‬\n‫رقــم ‪ 34260098‬وتاريــخ ‪1434/09/07‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف مبكــة املكرمــة‬\n‫رقــم ‪ 34297417‬وتاريــخ ‪1434/08/15‬ه ـ واملــدون علــى ظهــر الصــك‬\n‫املتضمــن املوافقــة علــى احلكــم باألكثريــة لــذا جــرى حتريــر ذلــك‬\n‫وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                            ‫وآلــه وســلم حــرر يف ‪1434/09/16‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد‬\n‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر من‬\n‫فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد (‪ )34276464‬وتاريــخ ‪1434/7/23‬ه ـ املتضمــن دعــوى منــدوب‬\n‫األوقــاف واملســاجد مبكــة املكرمــة ضــد واحملكــوم فيــه مبــا دون‬\n‫بباطنــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                           ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":305,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"662895a762f920705228b9871071402d383bb4f98bc3d215e7b3e94a51b4e86c","normalized_text_hash":"12b28d22cf653307725cb8d4fd00b9b0e5fdf91c679815f5d3dc3319426cd434","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p305-34276464"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"3e7aae23-9245-5ff1-80fb-04a176931dbb","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة املستأجر بفسخ إجارة عقار لتغير أجرة املثل- تعديل قيمة اإليجار باملثل أو فسخ العقد -وجوب الوفاء بالعقود- احلكم برد الدعوى .","document_number":"34194141","case_number":"33141857","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":"الدائرة احلقوقية الثانية املتضمن أنه بدراسة الصك وصورة ضبطه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"إجارة -مطالبة املستأجر بفسخ إجارة عقار لتغير أجرة املثل- تعديل قيمة اإليجار باملثل أو فسخ العقد -وجوب الوفاء بالعقود- احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34194141 :‬‬\n                    ‫َر ْق ُم الدعوى‪33141857 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34266654‬تاريخه‪1434/7/12 :‬هـ‬\n\n\n‫إجــارة ‪ -‬مطالبــة املســتأجر بفســخ إجــارة عقــار لتغيــر أجــرة املثــل‪-‬‬\n‫تعديــل قيمــة اإليجــار باملثــل أو فســخ العقــد ‪ -‬وجــوب الوفــاء بالعقــود‪-‬‬\n                                                      ‫احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n                    ‫قول اهلل تعالى‪ (( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n\n\n\n\n‫ادعــى وكيــل املدعــن بــأن املدعــى عليــه اســتأجر مــن موكليــه العقــار‬\n‫املوصــوف يف الدعــوى للمــدة واألجــرة املذكوريــن يف دعــواه وأنــه قــد‬\n‫مضــى جــزء مــن مــدة العقــد ثــم ارتفعــت أســعار اإليجــار يف املنطقــة عــن‬\n‫األجــرة املتعاقــد عليهــا‪ ،‬لــذا فقــد طلــب إلــزام املدعــى عليــه بتعديل قيمة‬\n‫األجــرة لتكــون كأجــرة املثــل أو فســخ العقــد‪ ،‬أقــر وكيــل املدعــى‬\n‫عليــه مبــا جــاء يف الدعــوى وقــرر بــأن موكلــه ال يوافــق علــى زيــادة‬\n‫األجــرة ألن بينــه وبــن املدعــن عقــد وهــو متمســك بــه‪ ،‬املدعــى عليــه‬\n‫بيــده عقــد إجــارة صحيــح واهلل عــز وجــل يقــول (( يــا أيهــا الذيــن آمنــوا‬\n‫أوفــوا بالعقــود))‪ ،.‬قضــت احملكمــة بــرد دعــوى املدعــن جتــاه املدعــى‬\n‫عليــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه وكيــل املدعــن‪،‬‬\n                      ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n                                                                                     ‫‪276‬‬\n\f      ‫العامــة‬\n          ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء حضر املدعي وكالة ‪........‬ســعودي اجلنســية مبوجب الســجل‬\n      ‫املدنــي رقــم ‪........‬حــال كونــه وكيــا عــن ‪........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪........‬و ‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪........‬و‪........‬اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪........‬و‪........‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬و‪........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪........‬وذلــك مبوجــب الوكالتــن الصــادرة مــن كتابــة‬\n      ‫عــدل الدمــام الثانيــة برقــم ‪ 6424‬و ‪1433/2/3‬ه ـ جلــد ‪ 9830‬ورقــم‬\n      ‫‪ 7225‬يف ‪1433/2/8‬ه ـ جلــد ‪ 9838‬كمــا حضــر املدعــى عليــه وكالــة‬\n      ‫‪........‬الســعودي مبوجــب الســجل املدنــي رقــم ‪........‬بصفتــه وكيــا عــن‬\n      ‫‪........‬مبوجــب الســجل املدنــي رقــم ‪........‬مبوجــب الوكالــة رقــم ‪17382‬‬\n      ‫وتاريــخ ‪1432/5/8‬ه ـ الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء‬\n      ‫و قــال املدعــي وكالــة يف حتريــر دعــواه إن موكلــي هــم ورثــة ‪........‬‬\n      ‫مبوجــب صــك حصــر اإلرث الصــادر مــن محكمــة الدمــام الكبــرى‬\n      ‫برقــم ‪ 3/5/22‬يف ‪1405/1/15‬ه ـ وقــد خلــف ملوكلــي عمــارة تقــع يف‬\n      ‫حــي ‪ ........‬باألحســاء اململوكــة مبوجــب الصــك الصــادر مــن كتابــة‬\n      ‫عــدل األحســاء برقــم ‪ 1/107‬وتاريــخ ‪1394/1/25‬ه ـ و هــي عبــارة عــن‬\n      ‫خمســة محــات وشــقة أرضيــة و شــقتني علويــة و قــد أجرهــا وكيــل‬\n‫‪277‬‬\n\f‫موكلــي يف تاريــخ ‪1423/7/16‬ه ـ مبوجــب وكالــة مــن موكلـ ّـي ملــدة‬\n‫عشرين سنة تبدأ من ‪1424/1/1‬هـ وتنتهي يف ‪1444/12/30‬هـ بأجرة‬\n‫ســنوية وقدرهــا ثالثــون ألــف ريــال وقــد مضــى علــى هــذه األجــرة تســع‬\n‫ســنوات وقــد زادت وارتفعــت أســعار اإليجــار يف املنطقــة وأجــرة مثيالتهــا‬\n‫اآلن مائــة و عشــرة آالف ريــال وموكلـ ّـي يطالبــون بإلــزام املدعــى عليــه‬\n‫بتعديــل قيمــة اإليجــار ليكــون كأجــرة املثــل أو فســخ العقــد هــذه‬\n‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره املدعــي وكالــة‬\n‫كلــه صحيــح فيمــا يتعلــق باألجــرة ومدتهــا ومقدارهــا وموكلـ ّـي ال‬\n‫يوافــق علــى زيــادة األجــرة وبينــه وبــن املدعــن عقــد وموكلــي متمســك‬\n‫بهــذا العقــد هكــذا أجــاب جــرى عــرض الصلــح بــن الطرفني ولــم يتفقا‬\n‫وقــال املدعــى عليــه وكالــة إن مقــدار أجــرة العمــارة يف الوقــت احلاضــر‬\n‫هــو ســتون ألــف ريــال وقــد أجرهــا موكلــي بهــذه األجــرة ومــا ذكــره‬\n‫املدعــي وكالــة يف اجللســة املاضيــة مبالــغ فيــه وقــال املدعــي وكالــة مــا‬\n‫ذكرتــه يف اجللســة املاضيــة هــو الصحيــح لــذا قــررت الكتابــة لقســم‬\n‫اخلبــراء بهــذه احملكمــة لتقديــر أجــرة العمــارة يف الوقــت احلاضــر ثــم‬\n‫وردنــا قــرار قســم اخلبــراء رقــم ‪ 139‬يف ‪143/03/02‬ه ـ املتضمــن نصــه‬\n‫(نفيدكــم بأنــه مت االســتعانة بأهــل اخلبــرة يف هــذا املجــال لالســتئناس‬\n‫برأيهــم و قــد مت التوصــل إلــى أن هــذا العقــار يقــدر يف الوقــت احلالــي‬\n‫بأجــرة ســنوية مببلــغ و قــدره ســبعون ألــف ريــال هــذا مــا مت التوصــل‬\n‫إليــه) انتهــى نصــه و بعرضــه علــى الطرفــن قــال املدعــي وكالــة إن‬\n‫مــا جــاء يف هــذا القــرار و تقديرهــم قريــب مــن الصحــة و ال زلــت علــى‬\n‫املطالبــة بفســخ العقــد أو تعديــل األجــرة و قــال املدعــى عليــه وكالــة‬\n‫إننــي غيــر مقتنــع بتقديــر قســم اخلبــراء و مــع موكلــي عقــد صحيــح‬\n\n\n                                                                                    ‫‪278‬‬\n\f      ‫ملــدة عشــرين ســنة مضــى عليــه أحــد عشــر ســنة و بقــي تســع ســنوات و‬\n      ‫متمســك بــه موكلــي فبنــاء علــى مــا تقــدم ومبــا أنــه بيــد املدعــى عليــه‬\n      ‫أصالــة عقــد إيجــار صحيــح وعقــد اإليجــار ملــزم للطرفــن ال ســيما مــع‬\n      ‫مضــي جــزء كبيــر منــه مــع عــدم املعارضــة وزيــادة األجــرة بعــد مضــي‬\n      ‫الوقــت غيــر مســوغ للمدعــي يف املطالبــة بفســخ العقــد أو زيــادة األجــرة‬\n      ‫لقولــه تعالــى‪ (( :‬يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود ‪ )...‬اآليــة ولــو ســاغ‬\n      ‫ذلــك ألدى إلــى عــدم اســتقرار العقــود وتضــرر الطــرف اآلخــر وتقديــر‬\n      ‫قســم اخلبــراء ألجــرة العقــار يف الوقــت احلاضــر ليــس فيــه زيــادة فاحشــة‬\n      ‫كمــا ذكــر املدعــي يف دعــواه ويف حــدود الزيــادة املعقولــة لــذا فلــم‬\n      ‫يثبــت لــي حــق للمدعــن فيمــا يطالبــون بــه ورددت دعواهــم جتــاه املدعــى‬\n      ‫عليــه وبذلــك حكمــت وبإعــان احلكــم قــرر املدعــى عليــه قناعتــه فيمــا‬\n      ‫قــرر املدعــي وكالــة عــدم القناعــة وطلب االســتئناف وأفهمتــه باملراجعة‬\n      ‫يــوم االثنــن ‪1434/4/22‬ه ـ الســتالم نســخت احلكــم واالعتــراض عليه‬\n      ‫خــال ثالثــن يــوم وإال ســقط حــق موكلــه باالعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/14‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/8/9‬ه ـ فتحــت اجللســة‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫وبرفقهــا القــرار رقــم ‪34266654‬وتاريخ‪1434/7/12‬ه ـ الصــادر مــن‬\n      ‫الدائــرة احلقوقيــة الثانيــة املتضمــن أنــه بدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫لــذا جــرى التهميــش وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":276,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ed4f9feb54d5b279b5f725dcc0e12c084af69d03843062f40d5acf62b7e7f8d5","normalized_text_hash":"5949cc61cee74af7eeda6380240d374d8cf7973be07f5e941a4e7b4502f8aa4b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p276-34194141"},{"id":"230e539d-7b0e-5d01-80d2-c6575b6ef396","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخال بشرط من شروط العقد -من ملك شيئا استوفاه بنفسه أو نائبه -املستأجر ميلك املنفعة -احلكم برد الدعوى لعدم مخالفة املدعى عليه ملقتضى العقد .","document_number":"34251380","case_number":"34202800","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/25","year":"1434","subject":"إجارة -إخال بشرط من شروط العقد -من ملك شيئا استوفاه بنفسه أو نائبه -املستأجر ميلك املنفعة -احلكم برد الدعوى لعدم مخالفة املدعى عليه ملقتضى العقد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/25 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34251380 :‬‬\n                    ‫َر ْق ُم الدعوى‪34202800 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34362571‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــال بشــرط مــن شــروط العقــد ‪ -‬مــن ملــك شــيئا اســتوفاه‬\n‫بنفســه أو نائبــه ‪ -‬املســتأجر ميلــك املنفعــة ‪ -‬احلكــم بــرد الدعــوى‬\n                        ‫لعــدم مخالفــة املدعــى عليــه ملقتضــى العقــد ‪.‬‬\n\n\n\n‫جــاء يف كشــاف القنــاع ‪(98/9‬ولــو شــرط عليــه اســتيفاءها أي املنفعــة‬\n‫بنفســه فســد الشــرط ولــم يجــز الوفــاء بــه ألنــه شــرط ينــايف مقتضــى‬\n‫العقــد إذ مقتضــاه امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبــه)‬\n                                                                         ‫أ‪.‬هـ‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه مبطالبتــه بفســخ عقــد اإليجــار‬\n‫ملخالفتــه العقد‪،‬حيــث اســتأجر املدعــى عليــه مــن املدعــي عمــارة‬\n‫بأجــرة ســنوية قدرهــا مائتــان وســتون ألــف ريــال علــى أن يؤجرهــا شــقق‬\n‫مفروشــة وقــد أجرهــا املدعــى عليــه لشــركة وهــو يخالــف العقــد وللبنــد‬\n‫الثانــي‪ ،‬صــادق املدعــى عليــه علــى اســتئجار العمــارة وأنكــر مخالفــة‬\n‫العقــد والنظــام‪ ،‬بينــة املدعــي عقــد اإليجــار‪ ،‬العقــد نــص علــى أحقيــة‬\n‫املســتأجر بتأجيــر العمــارة للغيــر دون الرجــوع للمالــك وهــو طبــق مــا دفــع‬\n‫بــه املدعــى عليــه‪ ،‬ومبــا أن املدعــى عليــه لم يخالف مقتضــى العقد املبرم‬\n\n                                                                                     ‫‪280‬‬\n\f      ‫بينهمــا واملســلمون علــى شــروطهم وألن املســتأجر ملــك املنفعــة مبجــرد‬\n      ‫العقــد ولــه التصــرف فيهــا فيمــا ال يضــر بالعــن املســتأجرة قــال صاحــب‬\n      ‫الكشــاف (‪( )98/9‬ولــو شــرط عليــه اســتيفاءها أي املنفعــة بنفســه‬\n      ‫فســد الشــرط ولــم يجــز الوفــاء بــه ألنــه شــرط ينــايف مقتضــى العقــد‬\n      ‫إذ مقتضــاه امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبــه)أ‪ ،.‬وهــذا‬\n      ‫علــى كــون صحــة شــرط املدعــي أن تكــون األجــرة يوميــة ولــم ينــص‬\n      ‫علــى ذلــك بالعقــد بــل نــص علــى خالفــه‪ ،‬لــم يثبــت اســتحقاق املدعــي ملــا‬\n      ‫يطلبــه مــن فســخ العقــد لعــدم مخالفــة املدعــى عليــه ملقتضــاه التعاقــدي‬\n      ‫والشــرعي‪ ،‬رد دعــوى املدعــي‪ ،‬اعتــرض املدعــي علــى احلكــم بالئحــة‬\n      ‫اعتراضيــة‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n                                            ‫االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n      ‫الســبت املوافق‪1434/5/25‬هـ لدي أنا ‪ ......‬القاضي باحملكمة العامة‬\n      ‫بينبــع بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n      ‫‪ 34202800‬وتاريــخ ‪1434/5/1‬ه ـ واملقيــدة برقــم ‪ 341081258‬وتاريــخ‬\n      ‫‪1434/5/1‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر ‪......‬‬\n      ‫ســعودي بالهويــة الوطنيــة رقــم ‪ ......‬وحضــر حلضــوره ‪ ......‬ســعودي بالهويــة‬\n      ‫الوطنيــة رقــم ‪ ......‬أدعــى املدعــي قائــا إنــه بتاريخ‪1434/4/4‬ه ـ أجــرت‬\n      ‫علــى املدعــى عليــه ‪.........‬الكائنــة أمــام احملكمــة العامــة بينبــع بأجــرة‬\n      ‫ســنوية مقدارهــا مائتــان وســتون ألــف ريــال على دفعتني كل ســتة أشــهر‬\n      ‫وقــد دفــع املئتــان والســتني ألــف كاملــة علــى أن يؤجرهــا شــقق مفروشــة‬\n‫‪281‬‬\n\f‫نظاميــة وقــد أجــر املدعــى عليــه العمــارة لشــركة وهــذا يخالــف النظــام‬\n‫ويخالــف العقــد ومــا جــاء يف بنــد رقم‪2‬ونصــه يتعهــد املســتأجر بعــدم‬\n‫التنــازل عــن العقــار لطــرف ثالــث مــا لــم يحصــل علــى موافقــة خطيــه‬\n‫مــن الطــرف األول أطلــب فســخ العقــد الــذي أبــرم بيننــا وأن يســلمني‬\n‫العقــار كمــا أســتلمه منــي هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n‫دعــوى املدعــي أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه مــن كونــه‬\n‫أجــر لــي العقــار املوصــوف بالصفــة التــي ذكرهــا فصحيــح ومــا ذكــره‬\n‫مــن أنــي خالفــت النظــام فغيــر صحيــح ولــم أخالــف العقــد أيضــا وقــد‬\n‫أجــرت للشــركة كشــقق مفروشــة وال يوجــد بالنظــام مــا مينــع مــن ذلــك‬\n‫هــذا جوابــي وبطلــب البينــة مــن املدعــي طلــب مهلــة وأجبتــه لطلبــه ويف‬\n‫جلســة أخــرى حضــر الطرفــان وبســؤال املدعــي للبينــة قــال بينتــي العقــد‬\n‫وبطلبــه أبــرز عقــدا صــادرا مــن مكتــب ‪ ...........‬للعقــار بينبــع وجدتــه‬\n‫يتضمــن تأجيــر املدعــي للمدعــى عليــه عمــارة مكونــة مــن أربعــة أدوار‬\n‫بحــي العمــودي ملــدة عشــر ســنوات اعتبــارا مــن تاريــخ ‪1434/4/1‬ه ـ‬\n‫مببلــغ مائتــن وســتني ألــف ريــال للســنة واإليجــار لكامــل العمــارة ســوى‬\n‫ثــاث محــات جتاريــة وأنــه يحــق للمســتأجر اإليجــار للغيــر دون الرجــوع‬\n‫للمالك وأن اإليجار شــقق مفروشــة اســتثمارية وصيانتها على املســتأجر‬\n‫مــن اســتثماره ‪ .‬أ ‪ .‬ه ـ مضمونــه وبســؤال املدعــى عليــه عــن العقــد املبــرم‬\n‫بينــه وبــن الشــركة قــال أطلــب مهلــة لذلــك وأضــاف ولكــن مت النــص‬\n‫يف عقــد اإليجــار علــى أنــه يحــق لــي إيجــار الغيــر بــدون الرجــوع للمالــك‬\n‫وهــذا يناقــض مــا ذكــره مــن أننــي خالفــت العقــد يف البنــد الثانــي ويف‬\n‫جلســة أخــرى حضــر املدعــي واملدعــى عليــه وبســؤال املدعــى عليــه‬\n‫عمــا طلــب منــه أبــرز عقــدا صــادرا مــن مكتــب ‪ ...‬للخدمــات العامــة‬\n\n\n                                                                                     ‫‪282‬‬\n\f      ‫والعقاريــة محــررا بتاريــخ ‪2013/3/1‬م ويتضمــن تأجيــر املدعــى عليــه‬\n      ‫للمواطــن ‪ ......‬العمــارة محــل الدعــوى بصفتهــا شــقق فندقيــة مجهــزة‬\n      ‫للســكن وذلــك لغــرض إســكان عمــال شــركته مــدة ســنتني وقيمــة‬\n      ‫األجــرة ســبعمائة وتســعة وعشــرون ألــف ريــال للســنة أ ‪ .‬ه ـ املقصــود‬\n      ‫منــه وبتالوتــه علــى املدعــي قــال إننــي اتفقــت معــه علــى تأجيــره إيجــارا‬\n      ‫يوميــا ثــم ســألت املدعــي هــل وقعــت علــى العقــد مبــا أضيــف إليــه قــال‬\n      ‫نعــم ولكننــي ال أقــرأ وال أكتــب هكــذا قــال فبنــاء علــى مــا ســبق مــن‬\n      ‫الدعــوى واإلجابــة ومبــا أن املدعــي طلــب فســخ العقــد املبــرم بينــه وبــن‬\n      ‫املدعــى عليــه إلدعائــه مخالفــة العقــد وذلــك بتأجيــره لشــركة فجــرى‬\n      ‫منــي اإلطــاع علــى العقــد املبــرم بينهمــا املرصــود مضمونــه بعاليــه وإذا‬\n      ‫بــه ينــص يف البنــد الثانــي مــن امللحوظــات بأنــه يحــق للمســتأجر اإليجــار‬\n      ‫للغيــر دون الرجــوع للمالــك أ ‪ .‬ه ـ ويف البنــد الثالــث أن اإليجــار شــقق‬\n      ‫مفروشــة اســتثمارية وصيانتــه علــى املســتأجر أو مــن اســتأجره أ ‪ .‬ه ـ‬\n      ‫وباالطــاع علــى مــا أبرمــه املدعــى عليــه مــع مــن أجــره املرصــود مضمونه‬\n      ‫بعاليــه وإذا بــه ينــص علــى أن اإليجــار لشــقق فندقيــة مجهــزة للســكن‬\n      ‫ونــص علــى عــدد الســاكنني وهــم مائــة وخمســة وثالثــن فــردا أ ‪ .‬ه ـ‬\n      ‫فبنــاء علــى مــا ســبق وألن املدعــى عليــه لــم يخالــف مقتضــى العقــد املبــرم‬\n      ‫بينهمــا واملســلمون علــى شــروطهم وألن املســتأجر ملــك املنفعــة مبجــرد‬\n      ‫العقــد ولــه التصــرف فيهــا فيمــا ال يضــر بالعــن املســتأجرة قــال صاحــب‬\n      ‫الكشــاف(‪()98/9‬ولو شــرط عليــه اســتيفاءها أي املنفعــة بنفســه فســد‬\n      ‫الشــرط ولــم يجــز الوفــاء بــه ألنه شــرط ينــايف مقتضى العقــد إذ مقتضاه‬\n      ‫امللــك ومــن ملــك شــيئا اســتوفاه بنفســه وبنائبه)أ‪.‬ه ـ وهــذا علــى كــون‬\n      ‫صحــة شــرط املدعــي أن تكــون األجــرة يوميــة ولــم ينــص علــى ذلــك يف‬\n\n\n‫‪283‬‬\n\f‫العقــد بــل نــص علــى خالفــه ولــكل مــا ســبق فلــم يثبــت لــدي اســتحقاق‬\n‫املدعــي ملــا يطلبــه مــن فســخ العقــد لعــدم مخالفــة املدعــى عليــه ملقتضــاه‬\n‫التعاقــدي والشــرعي ورددت دعــوى املدعــي وأخليــت ســبيل املدعــى‬\n‫عليــه هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى املدعــي قــرر عــدم‬\n‫قناعتــه باحلكــم وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــه‬\n‫فجــرى تســليمه نســخة مــن صــك احلكــم وأفهــم بــأن لــه ثالثــن يومــا‬\n‫مــن تاريــخ هــذا اليــوم وإذا مضــت املــدة ولــم يقــدم اعتراضــه خاللهــا‬\n‫اكتســب احلكــم الصفــة القطعيــة وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/06/24‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس املوافــق ‪ 1434/10/22‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثانيــة عشــر وفيهــا حضــر املدعــي وقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بكتــاب فضيلــة‬\n‫رئيــس محكمــة االســتئناف رقــم ‪ 341081258‬وتاريــخ ‪1434/8/17‬ه ـ‬\n‫مرفقــا بــه قــرار الدائــر احلقوقيــة الثانيــة رقــم ‪ 34293510‬وتاريــخ‬\n‫‪1434/8/10‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة «وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا ملالحظــة مــا يلــي‬\n‫‪ -1‬لــم يطلــب فضيلــة ناظــر القضيــة مــن املدعــي مــا يثبــت متلكــه للعمارة‬\n‫املؤجــرة ولــم يرفــق مــا يفيــد ذلــك بــأوراق املعاملــة ‪ -2‬تصويــب األخطــاء‬\n‫اإلمالئيــة والنحويــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم « أ‪ .‬ه ـ بختــم وتوقيع أصحــاب الفضيلة قضاة الدائرة‬\n‫ولوجاهــة مــا أشــار إليــه أصحــاب الفضيلــة ســددهم اهلل فقــد طلبــت مــن‬\n‫املدعــي مــا يثبــت ملكيتــه للعقــار فأبــرز الصــك الشــرعي الصــادر مــن‬\n‫كتابــة عــدل ينبــع برقــم ‪ 3/2/1927‬وتاريــخ ‪1422/3/11‬ه ـ املتضمــن‬\n\n\n                                                                                      ‫‪284‬‬\n\f      ‫متلــك املدعــي للعمــارة املوصوفــة محــل الدعــوى وأمــا بخصــوص اخلطــأ‬\n      ‫املشــار إليــه يف الســطر اخلامــس فــإن صحتــه (املائتــن و الســتني ألــف)‬\n      ‫ويف الســطر اخلامــس والعشــرين صحــة العبــارة الــواردة فيــه (ورددت‬\n      ‫دعــوى املدعــي) بــدال مــن املدعــى عليــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                 ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر ‪1434/10/22‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بينبــع املســاعد الشــيخ ‪ ......‬برقــم ‪341081258‬‬\n      ‫وتاريــخ ‪1434/10/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلتــه برقــم‬\n      ‫‪ 34251380‬وتاريــخ ‪1434/6/25‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ......‬ضــد ‪، ......‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪285‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":280,"source_page_end":285,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b377d1f42a7ed9c9930d4fc770702dccf3f2fc1237fb914327fdea7e43499efc","normalized_text_hash":"86a45c8c5d661a28f7c97b1af868c58d4b61974ad607be4e862d1e6474a552aa","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p280-34251380"},{"id":"22247769-4375-53e1-b580-1ecae33f0976","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لعدم معرفة عنوان املدعى عليه -العقد بينة املدعي -احلكم بإخاء العن- الغائب على حجته متى حضر.","document_number":"34309503","case_number":"34232323","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/30","year":"1434","subject":"إجارة -إخاء عقار من غائب -سماع الدعوى غيابي ا لعدم معرفة عنوان املدعى عليه -العقد بينة املدعي -احلكم بإخاء العن- الغائب على حجته متى حضر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/30 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34309503 :‬‬\n                    ‫َر ْق ُم الدعوى‪34232323 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34325311‬تاريخه‪1434/9/24:‬هـ‬\n\n\n‫إجــارة ‪ -‬إخــاء عقــار مــن غائــب ‪ -‬ســماع الدعــوى غيابيـ ًا لعــدم معرفــة‬\n‫عنــوان املدعــى عليــه ‪ -‬العقــد بينــة املدعــي ‪ -‬احلكــم بإخــاء العــن‪-‬‬\n                                        ‫الغائــب علــى حجتــه متــى حضــر‪.‬‬\n\n\n\n\n                               ‫قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه الغائب عن مجلــس احلكم بأن املدعى‬\n‫عليــه اســتأجر غرفــة يف العمــارة الواقعــة يف ‪ ......‬بينبــع الصناعيــة بأجــرة‬\n‫ـداء مــن ‪1433/09/15‬ه ـ‬    ‫شــهرية قدرهــا ألــف ريــال تدفــع ملــدة ســنة ابتـ ً‬\n‫إلــى ‪1434/09/15‬ه ـ وقــد ســلمه مــن األجــرة أربعــة أشــهر وإنــه مــن‬\n‫تاريــخ ‪1434/02/15‬ه ـ حتــى تاريــخ اليــوم لــم يســتلم منــه مبلــغ األجــرة‬\n‫الــذي يخصهــا وقــدره ســتة آالف ريــال وقــد حلقــه الضــرر مــن تعطيــل‬\n‫الغرفــة وعــدم دفــع األجــرة ويطلــب إلــزام املدعــى عليــه بإخــاء العقــار‬\n‫فــور ًا هكــذا ادعــى‪ ،‬املدعــى عليــه ال يعــرف لــه عنــوان حيــث جــرى‬\n‫مخاطبــة عملــه لتبليغــه فــوردت اإلفــادة بأنــه منقطــع عــن العمــل فجــرى‬\n‫ســماع الدعــوى غيابي ـاً‪ ،‬بينــة املدعــي عقــد اإليجــار ‪ ،‬ويســري العقــد‬\n‫ملــدة ســنة مــن تاريخ‪1433/09/15‬ه ـ ‪ ،‬ولتعــذر إبــاغ املدعــى عليــه ‪،‬‬\n\n                                                                                     ‫‪286‬‬\n\f      ‫وملــا أبــداه املدعــي مــن وقــوع الضــرر عليــه يف تأخــر املدعــى عليــه يف‬\n      ‫دفــع األجــرة وعــدم إخــاء الغرفــة محــل الدعــوى‪ ،‬ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم (ال ضــرر وال ضــرار) وألن هــذا مــن الضــرر الــذي يلحــق‬\n      ‫النــاس يف أموالهــم وقــد جــاءت الشــريعة اإلســامية بحفظــه وألن العقــد‬\n      ‫بينــة املدعــي وينتهــي أجلــه يف التاريــخ الــذي ذكــره املدعــي‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم علــى املدعــى عليــه الغائــب بإخــاء الغرفــة املذكــورة يف‬\n      ‫الدعــوى يف أجــل انتهــاء العقــد يف‪1434/09/15‬ه ـ والغائــب علــى حجتــه‬\n      ‫متــى حضــر‪ ،‬رفــع احلكــم إلــى محكمــة االســتئناف لتدقيقــه‪ ،‬صــدق‬\n      ‫احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف مبنطقــة‬\n                                                                  ‫مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة لــه مــن‬\n                                           ‫بينبــع والقائــم بعمــل القاضــي ‪......‬وبنـ ً‬\n      ‫فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بينبــع برقــم ‪34232323‬‬\n      ‫وتاريــخ ‪1434/05/20‬ه ـ املقيــدة باحملكمــة برقــم ‪341228955‬‬\n      ‫وتاريــخ ‪1434/05/20‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ا يف‬ ‫املدنــي رقــم ‪......‬وادعــى علــى الغائــب عــن املجلــس الشــرعي‪ ......‬قائـ ً‬\n      ‫دعــواه إنــه بتاريــخ ‪1433/09/07‬ه ـ مت االتفــاق بينــي وبــن املدعــى عليــه‬\n      ‫علــى أن يســتأجر املدعــى عليــه غرفــة يف العمــارة الواقعــة يف حــي ‪......‬‬\n      ‫بينبــع الصناعيــة بأجــرة شــهرية قدرهــا (‪ ) 1,000‬ألــف ريــال تدفــع ملــدة‬\n      ‫ـداء مــن ‪1433/09/15‬ه ـ إلــى ‪1434/09/15‬ه ـ وقــد ســلمني‬             ‫ســنة ابتـ ً‬\n‫‪287‬‬\n\f‫مــن األجــرة أربعــة أشــهر وإنــه مــن تاريــخ ‪1434/02/15‬ه ـ حتــى تاريــخ‬\n‫اليــوم لــم اســتلم منــه مبلــغ األجــرة الــذي يخصهــا وقــدره ( ‪ ) 6,000‬ســتة‬\n‫آالف ريــال أطلــب إلــزام املدعــى عليــه بإخــاء العقــار فــور ًا هكــذا ادعى‬\n‫وقــد ســبق الكتابــة إلدارة األمــن الصناعــي بينبــع الصناعيــة باخلطــاب‬\n‫ذي الرقــم‪ 341367049‬وتاريخ‪1434/06/11‬ه ـ إلبــاغ املدعــى عليــه‬\n‫مبوعــد اجللســة يــوم الســبت املوافق‪1434/06/24‬ه ـ الســاعة الثامنــة‬\n‫والنصــف فوردنــا خطابهــم ذي الرقــم‪ 125298‬وتاريخ‪1434/06/20‬ه ـ‬\n‫املتضمن‪0‬إشــارة إلــى خطابكــم رقــم‪ ......‬وتاريخ‪1434/06/11‬ه ـ‬\n‫املتضمــن طلبكــم تكليــف املوظــف ‪......‬مبراجعتكــم عليــه نفيدكــم‬\n‫بــأن املذكــور منقطــع عــن العمــل مــن تاريخ‪1433/12/01‬ه ـ وحتــى‬\n‫تاريخــه ومرفــق لكــم كامــل املعاملة)ا‪.‬ه ـ وبســؤال املدعــي عــن بينتــه‬\n‫التــي تشــهد بصحــة دعــواه فأبــرز عقــد إيجــار صــادر مــن مكتــب‬\n‫‪...‬للعقــار وإدارة األمــاك برقــم‪ 59‬وتاريخ‪1433/09/07‬ه ـ وباالطــاع‬\n‫عليــه وجدتــه مطابــق ملــا ذكــره املدعــي يف دعــواه و‪......‬وتوقيــع الطــرف‬\n‫األول ‪......‬و‪ ......‬وتوقيــع الطــرف الثانــي ‪ ......‬ثــم جــرى منــي ســؤال‬\n‫املدعــي هــل لديــه زيــادة بينــه علــى مــا ذكــره فأجــاب بقولــه ليــس لــدي‬\n‫ســوى مــا ذكرتــه ويف جلســة أخــرى لــدي أنــا ‪......‬القاضــي باحملكمــة‬\n‫العامــة بينبــع والقائــم بعمــل املكتــب القضائــي اخلامــس مبوجــب قــرار‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد رقــم ‪341935902‬‬\n‫وتاريخ‪1434/08/09‬ه ـ ففــي يــوم االثنــن املوافــق ‪ 1434/08/29‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه وال‬\n‫وكيلــه وجــرى عــرض مــا ســبق علــى املدعــي فصــادق علــى مــا جــاء فيه‪،‬‬\n‫وأضــاف‪ :‬إنــي قــد حلقنــي الضــرر مــن تعطيــل الغرفــة املذكــورة وعــدم‬\n\n\n                                                                                    ‫‪288‬‬\n\f      ‫دفــع األجــرة وتغيــب املدعــى عليــه وال يعــرف لــه عنــوان أطلــب احلكــم‬\n      ‫بإلزامــه بإخــاء الغرفــة املذكــورة النتهــاء األجــل يف‪1434/09/15‬ه ـ‬\n      ‫هكــذا قــال ‪ ،‬وعليــه طلبــت مــن املدعــي البينــة علــى صحــة دعــواه فأبرز‬\n      ‫العقــد املــدون علــى أوراق مكتــب ‪...‬للعقار برقم‪ 59‬يف ‪1433/09/07‬هـ‬\n      ‫املتضمــن تأجيــر املدعــي للمدعــى عليــه للغرفــة بعمارتــه الكائنة يف حي‬\n      ‫‪ ،......‬ويســري العقــد ملــدة ســنة مــن تاريخ‪1433/09/15‬ه ـ وقــد جــرى‬\n      ‫إرفــاق صــورة مــن العقــد يف املعاملــة وعليــه وملــاء جــاء يف الدعــوى ولتعــذر‬\n      ‫إبــاغ املدعــى عليــه ‪ ،‬وملــا أبــداه املدعــي مــن وقــوع الضــرر عليــه يف تأخــر‬\n      ‫املدعــى عليــه يف دفــع األجــرة وعــدم إخالء الغرفة محل الدعوى‪ ،‬ولقوله‬\n      ‫صلــى اهلل عليــه وســلم‪»:‬ال ضــرر وال ضــرار» وألن هــذا مــن الضــرر الــذي‬\n      ‫يلحــق النــاس يف أموالهــم وقــد جــاءت الشــريعة اإلســامية بحفظــه وألن‬\n      ‫العقــد بينــة املدعــي وينتهــي أجلــه يف التاريــخ الــذي ذكــره املدعــي لــذا‬\n      ‫فقــد حكمــت علــى املدعــى عليــه الغائــب بإخــاء الغرفــة املذكــورة يف‬\n      ‫الدعــوى يف أجــل انتهــاء العقــد يف‪1434/09/15‬ه ـ والغائــب علــى حجتــه‬\n      ‫متــى حضــر وقــررت رفــع احلكــم مــع املعاملــة إلــى محكمــة االســتئناف‬\n      ‫لتدقيقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/29‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪....../‬القاضي باحملكمــة العامــة بينبــع واملســجل بعــدد ‪......‬‬\n      ‫وتاريــخ ‪1434/8/30‬ه ـ املتضمــن دعــوى ‪......‬ضــد ‪ ......‬واحملكــوم فيــه‬\n      ‫مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n\n\n‫‪289‬‬\n\f‫احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                         ‫‪290‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":286,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"902040fb63608d57f49b33212c12944562b48f10ac56d1655b3abffa0df6eb80","normalized_text_hash":"4e0f42eab1ac8f455d8882cba26e2e1a09677b6357481c887777926f57f3aa64","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p286-34309503"},{"id":"fd991337-ccdc-5835-9f25-ec40cee20c0b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -امتناع املدعى عليه عن دفع األجرة مقابل استخدام العقار- مطالبة املدعى عليه بسداد األجرة وإخاء العقار -تذرع املدعى عليه بعيب يف العقار -شهادة الشهود العدول -استخدام العقار اء بالعيب -اإللزام فترة طويلة دون املطالبة بفسخ العقد يعد رض بدفع مبلغ اإليجار وإخاء العقار .","document_number":"34259894","case_number":"303751122","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":"الدائرة احلقوقية الرابعة رقم 34341849 :يف1434/10/27 :ه ونص","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434 /7/4","year":"1434","subject":"إجارة -امتناع املدعى عليه عن دفع األجرة مقابل استخدام العقار- مطالبة املدعى عليه بسداد األجرة وإخاء العقار -تذرع املدعى عليه بعيب يف العقار -شهادة الشهود العدول -استخدام العقار اء بالعيب -اإللزام فترة طويلة دون املطالبة بفسخ العقد يعد رض بدفع مبلغ اإليجار وإخاء العقار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434 /7/4 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34259894 :‬‬\n                         ‫َر ْق ُم الدعوى‪303751122 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34341849‬تاريخه‪1434/10/27 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬امتنــاع املدعــى عليــه عــن دفــع األجــرة مقابــل اســتخدام العقار‪-‬‬\n      ‫مطالبــة املدعــى عليــه بســداد األجــرة وإخــاء العقــار‪ -‬تــذرع املدعــى‬\n      ‫عليــه بعيــب يف العقــار‪ -‬شــهادة الشــهود العــدول‪ -‬اســتخدام العقــار‬\n      ‫ـاء بالعيــب‪ -‬اإللــزام‬\n                           ‫فتــرة طويلــة دون املطالبــة بفســخ العقــد يعــد رضـ ً‬\n                                          ‫بدفــع مبلــغ اإليجــار وإخــاء العقــار ‪.‬‬\n\n\n\n\n      ‫قــال ابــن تيميــه يف مختصــر الفتــاوى ‪( 412/1‬وتأخــر الدعــوى املمكنــة‬\n                    ‫يف مســائل اجلــور ونحوهــا يــدل علــى كــذب املدعــى بهــا)‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي أصالــة ووكالــة ضــد املدعــى عليــه بالوكالــة عــن‬\n      ‫صاحــب مؤسســة بــأن صاحــب املؤسســة قــد اســتأجر الــدور الثانــي مــن‬\n      ‫املجمــع التجــاري اململــوك للمدعــي وموكلــه ملــدة تســع ســنوات وقــرر‬\n      ‫املدعــي أصالــة ووكالــة أنــه بقــى مــن األجــرة لعــام ‪1432‬ه ـ مبلغـ ًا قــدره‬\n      ‫خمســة وعشــرون ألــف ريــال كمــا بقــي أجــرة الســنتني األخيرتــن مبلغـ ًا‬\n      ‫قــدره ســبعمائة وخمســون ألــف ريــال وطالــب املدعــي أصالــة ووكالــة‬\n      ‫بتســليم األجــرة احلالــة وإخــاء العقــار موطــن الدعــوى‪ ،‬صــادق املدعــى‬\n      ‫ا وذكــر أن ســبب عــدم‬      ‫عليــه وكالــة علــى الدعــوى جملــة وتفصي ـ ً‬\n\n‫‪291‬‬\n\f‫دفــع املبلــغ هــو أن املدعــي قــام بإزالــة مخــرج الطــوارئ خلــف العقــار‬\n‫محــل النــزاع وعــدم إصــاح مضخــات امليــاه للحرائــق وقــد تضــررت‬\n‫املؤسســة مــن جهــة تأخيــر اســتخراج تصاريــح الدفــاع املدنــي وفــات علــى‬\n‫املؤسســة التعاقــد يف مشــاريع تعليميــة واملؤسســة ملتزمــة باخلــروج يف‬\n‫‪1434/12/30‬ه ـ علمـ ًا بــأن املؤسســة مســتغلة للعقــار محــل النــزاع حتــى‬\n‫تاريخــه وتقيــم فيــه دورات لكنهــا لــم حتصــل علــى تصاريــح اجلهــات‬\n‫املختصة‪،‬احضــر املدعــي أصالــة ووكالــة شــاهدين مت تعديلهمــا شــرع ًا‬\n‫وشــهدا أن املؤسســة املدعــى عليهــا قــد اســتلمت العقــار محــل النــزاع‬\n‫بوضعــه احلالــي متامـ ًا وأن املؤسســة لهــا مخــرج طــوارئ خلــف املبنــى وأنــه‬\n‫لــم ينشــأ درج داخــل الســوبرماركت‪ ،‬قــرر ناظــر القضيــة أنــه بنــاء‬\n‫علــى مــا ســبق وأنــه علــى فــرض التســليم بــأن املدعــي قــام بإزالــة مخــرج‬\n‫الطــوارئ وأنــه لــم يقــم بإصالحــات مضخــات امليــاه للحرائــق فــإن تســليم‬\n‫املدعــى عليهــا ألجــرة عــام ‪1432‬ه ـ واســتخدام العقــار فتــرة طويلــة دون‬\n‫املطالبــة بفســخ العقــد يعــد رضــا بالعيــب كمــا أن دفــع املدعــى عليــه‬\n‫وكالــة بــأن درج الطــوارئ هــو الــذي داخــل الســوبر ماركــت غيــر وجيــه‬\n‫ألنــه يســتحيل أن يكــون مخــرج الطــوارئ داخــل محــل جتــاري كمــا أن‬\n‫الوكيــل ذكــر يف جوابــه علــى الدعــوى أن الــدرج خلــف املبنــى كمــا‬\n‫أن املدعــي وكالــة قــدم بينــة تؤيــد عــدم صحــة دفــع املدعــى عليــه لذلــك‬\n‫كلــه صــدر احلكــم علــى املدعــى عليهــا بتســليم املدعــي وموكلــه‬\n‫األجــرة احلالــة واحلكــم بإخــاء العقــار بتاريــخ ‪1434/12/30‬هــ‪ ،‬قــرر‬\n‫املدعــى عليــه وكالــة عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                                                       ‫باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــدة‪ /‬املســاعد برقــم ‪303751122‬‬\n      ‫وتاريــخ ‪1431/12/16‬ه ـ املقيــدة باحملكمــة برقــم ‪31101226‬‬\n      ‫وتاريــخ ‪1431/12/16‬ه ـ وبعــد عــدة جلســات ففــي يــوم اإلثنــن املوافــق‪:‬‬\n      ‫‪1434/06/26‬ه ـ حضــر‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪ ........ :‬باألصالــة عــن نفســه وبالوكالــة عــن‪، ........ :‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجــدة رقــم‪........ :‬‬\n      ‫يف‪1431/6/18 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وحضــور‬\n      ‫اجللســات واســتالم احلقــوق مبوجــب شــيك باســم موكلــه والقناعــة‬\n      ‫باألحــكام واالعتــراض عليهــا وطلــب التحكيــم‪ .‬ا‪ .‬ه ـ وحضــر حلضوره‪:‬‬\n      ‫‪ ، ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪ ........ :‬الوكيــل‬\n      ‫عــن‪ ........‬بصفتــه صاحــب مؤسســة ‪ ، ........‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بشــمال جــدة رقــم‪ ........ :‬يف‪1434/6/24 :‬ه ـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وســماع الدعــوى والــرد عليهــا‬\n      ‫واإلقــرار واإلنــكار والصلــح والتنــازل‪ .‬ا‪ .‬ه ـ وادعــى األول قائــا‪ :‬إننــي‬\n      ‫أملــك أنــا وموكلــي عقــار يقــع طريــق األميــر ‪ ........‬ـ حــي ‪ ........‬وهــو‬\n      ‫عبــارة عــن مجمــع جتــاري واســمه (مركــز ‪ ،) ........‬وقــد اســتأجرت‬\n      ‫‪ ........‬الــدور الثانــي كامــا ملــدة تســع ســنوات اعتبــارا مــن تاريــخ‬\n      ‫‪1424/1/1‬ه وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ بأجــرة ســنوية للســنوات‬\n      ‫الثــاث األولــى وقدرهــا‪ :‬ثــاث مئــة وخمســة وعشــرون ألــف ريــال‪،‬‬\n\n‫‪293‬‬\n\f‫وللثــاث الســنوات الثانيــة بأجــرة ســنوية قدرهــا‪ :‬ثــاث مئــة وخمســون‬\n‫ألــف ريــال‪ ،‬وللثــاث الســنوات الثالثــة بأجــرة ســنوية قدرهــا‪ :‬ثــاث‬\n‫مئــة وخمســة وســبعون ألــف ريــال‪ ،‬وقــد التزمــت املؤسســة املدعــى‬\n‫عليهــا بدفــع األجــرة طيلــة الفتــرة الســابقة‪ ،‬وبقــي عليهــا مــن أجــرة عــام‬\n‫‪1432‬ه ـ مبلغــا قــدره‪ :‬واحــد وثالثــون الــف وثــاث مئــة وســبعة وخمســن‬\n‫ريــال لــم تســددها‪ ،‬كمــا أنهــا لــم تســدد أجــرة العقــار محــل النــزاع‬\n‫للســنتني‪1433 :‬ه ـ ‪1434‬ه ـ ‪ ،‬أطلــب إلــزام املؤسســة املدعــى عليهــا مبــا‬\n‫يلــي‪ ،‬أوال‪ :‬ســداد املبلــغ املتبقــي مــن أجــرة العقــار محــل النــزاع لعــام‪:‬‬\n‫‪1432‬ه ـ وقدرهــا‪ :‬واحــد وثالثــون الــف وثــاث مئــة وســبعة وخمســن‬\n‫ريــال‪ .‬ثانيــا‪ :‬ســداد أجــرة العقــار محــل النــزاع لعــام‪1433 :‬ه ـ وقدرهــا‪:‬‬\n‫ثــاث مئــة وخمســة وســبعون ألــف ريــال‪ .‬ثالثــا‪ :‬ســداد أجــرة العقــار محــل‬\n‫النــزاع لعــام‪1434 :‬ه ـ وقدرهــا‪ :‬ثــاث مئــة وخمســة وســبعون ألــف ريــال‪.‬‬\n‫رابعــا‪ :‬إخــاء العقــار محــل النــزاع بتاريــخ‪1434/12/30 :‬ه ـ ‪ ،‬هكــذا‬\n‫ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬أطلــب‬\n‫مهلــة لإلجابــة‪ ،‬هكــذا أجــاب‪ .‬ويف يــوم الثالثاء املوافــق ‪1434/6/27‬هـ‬\n‫حضــر املدعــي أصالــة ووكالــة‪ ، ........ :‬واملدعــى عليــه وكالــة‪........ :‬‬\n‫املثبــت حضورهمــا يف جلســة ســابقة‪ ،‬وبســؤال املدعى عليــه وكالة عما‬\n‫اســتمهل مــن أجلــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي أنــه ميلك هــو موكله‬\n‫العقــار الــذي يقــع طريــق األميــر ‪ ........‬ـ حــي ‪ ........‬وهــو عبــارة عــن مجمــع‬\n‫جتــاري واســمه (مركــز ‪ ) ........‬فصحيــح‪ ،‬ومــا ذكــره أن موكلتــي ـ‬\n‫مؤسســة ‪ ........‬ـ قــد اســتأجرت الــدور الثانــي كامــا ملــدة تســع ســنوات‬\n‫اعتبــارا مــن تاريــخ‪1424/1/1 :‬ه ـ وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ‬\n‫بأجــرة ســنوية للســنوات الثــاث األولــى وقدرهــا‪ :‬ثــاث مئــة وخمســة‬\n\n\n                                                                                           ‫‪294‬‬\n\f      ‫وعشــرون ألــف ريــال‪ ،‬وللثــاث الســنوات الثانيــة بأجــرة ســنوية قدرهــا‪:‬‬\n      ‫ثــاث مئــة وخمســون ألــف ريــال‪ ،‬وللثالث الســنوات الثالثة بأجرة ســنوية‬\n      ‫قدرهــا‪ :‬ثــاث مئــة وخمســة وســبعون ألــف ريــال فصحيــح‪ ،‬ومــا ذكــره‬\n      ‫أن موكلتــي قــد التزمــت بدفــع األجــرة طليلــة الفتــرة الســابقة‪ ،‬وبقــي‬\n      ‫عليهــا مــن أجــرة عــام ‪1432‬ه ـ مبلغــا قــدره‪ :‬واحــد وثالثــون ألــف وثــاث‬\n      ‫مئــة وســبعة وخمســن ريــال لــم تســددها فغيــر صحيــح‪ ،‬والصحيــح أنــه‬\n      ‫بقــي مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪ :‬خمســة وعشــرون ألــف ريــال‪،‬‬\n      ‫ومــا ذكــره أن موكلتــي لــم تســدد أجــرة العقــار محــل النــزاع للســنتني‪:‬‬\n      ‫‪1433‬ه ـ ‪1434‬ه ـ فصحيــح وهــي حالــة‪ ،‬وســبب امتنــاع موكلتــي مــن‬\n      ‫تســديد أجــرة الســنتني هــي أن املدعــي قــام بإزالــة مخــرج الطــوارئ‬\n      ‫الواقــع خلــف املبنــى مــن العقــار محــل النــزاع‪ ،‬وعــدم إصــاح مضخــات‬\n      ‫املــاء للحرائــق‪ ،‬وتضــررت موكلــي مــن جهــة تأخيــر اســتخراج تصاريــح‬\n      ‫الدفــاع املدنــي بســبب ذلــك‪ ،‬وقــد فــات علــى موكلتــي تعاقــد يف‬\n      ‫مشــاريع تعليميــة بجــدة حيــث إن العقــد يســتلزم رخصــة الدفــاع املدنــي‪،‬‬\n      ‫وموكلتــي ملتزمــة باخلــروج بتاريــخ‪1434/12/30 :‬ه ـ وأطلــب رد دعــوى‬\n                       ‫املدعــي وإخــاء ســبيل موكلتــي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبعــرض ذلــك علــى املدعــي أجــاب قائال‪ :‬ما ذكره املدعى عليه وكالة‬\n      ‫مــن جهــة التصاريــح وإزالــة مخــرج الطــوارئ فغيــر صحيــح‪ ،‬ومــا ذكــره‬\n      ‫أن املتبقــي خمســة وعشــرون ألــف ريــال فصحيــح‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه أجــاب قائــا‪ :‬ليــس لــدي بينــة‪ ،‬وأطلــب الوقــوف علــى‬\n      ‫العقــار محــل النــزاع لالطــاع عليــه‪ ،‬هكــذا أجــاب‪ .‬ثــم أضــاف املدعــي‬\n      ‫قائــا‪ :‬إن املدعــى عليــه وكالــة قصــده اللــدد وإطالــة أمــد الترافــع وهــذا‬\n      ‫ظاهــر مــن ســير الدعــوى‪ ،‬ولــدي البينــة علــى أن مخــرج الطــوارئ لــم‬\n\n\n‫‪295‬‬\n\f‫يــزال وهــو علــى حالــه‪ ،‬وأطلــب مهلــة إلحضارهــا‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن تاريــخ إزالــة املدعــي ملخــرج الطــوارئ‬\n‫أجــاب قائــا‪ :‬أطلــب مهلــة لإلجابــة‪ ،‬هكــذا أجــاب‪ .‬ويف يــوم األحــد‬\n‫املوافــق‪1434/07/02 :‬ه ـ حضــر املدعــي أصالــة ووكالــة‪،........ :‬‬\n‫وحضــر حلضــوره‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم‪ ........ :‬الوكيــل عــن‪ ........ :‬بصفتــه صاحــب مؤسســة ‪،........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة‬\n‫رقــم‪ ........ :‬يف‪1434/6/24 :‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n‫وســماع الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل‪.‬‬\n‫ا‪ .‬ه ـ وبســؤال املدعــى عليــه وكالــة عــن تاريــخ إزالــة املدعــي ملخــرج‬\n‫الطــوارئ أجــاب قائــا‪ :‬ال أذكــره بالتحديــد لكنــه أزال مضخــات‬\n‫احلرائــق ومخــارج الطــوارئ يف عــام‪1431 :‬ه ـ هكــذا أجــاب‪ .‬وبســؤاله‬\n‫عــن العقــار أجــاب قائــا‪ :‬موكلتــي مســتغلّة للعقــار محــل النــزاع حتــى‬\n‫تاريــخ اليــوم وتقيــم فيــه دورات لكــن لــم حتصــل علــى تراخيــص مــن‬\n‫املختصــة هكــذا أجــاب‪ .‬وبســؤال املدعــي أصالــة ووكالــة عمــا‬‫ّ‬        ‫اجلهــات‬\n‫اســتمهل مــن أجلــه أجــاب قائــا‪ :‬أطلــب مهلــة ثانيــة إلحضارهــا‪ ،‬هكذا‬\n‫أجــاب‪ .‬ويف يــوم الثالثــاء املوافــق‪1434/07/04 :‬هـ حضر املدعي أصالة‬\n‫ووكالــة‪ ، ........ :‬واملدعــى عليــه وكالــة‪ ، ........ :‬املثبــت حضورهمــا يف‬\n‫جلســة ســابقة‪ ،‬وبســؤال املدعــي أصالــة ووكالــة عمــا اســتمهل مــن أجله‬\n‫أحضــر للشــهادة وأدائهــا اثنــن؛ األول‪ ، ........ :‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة الوطنيــة رقــم‪ ........ :‬وهــو مــن مواليــد عــام‪1410 :‬ه ـ ويســكن يف‬\n‫يف النــزاع‪ ،‬والثانــي‪:‬‬‫معقــب‪ ،‬وليــس لــه عالقــة بطــر ّ‬\n                                                        ‫حــي ‪ ، ........‬ويعمــل ّ‬\n‫‪ ، ........‬لبنانــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ........ :‬وهــو مــن‬\n\n\n                                                                                     ‫‪296‬‬\n\f      ‫مواليــد عــام‪1393 :‬ه ـ ويســكن يف حــي ‪ ، ........‬ويعمــل يف مؤسســة‬\n      ‫‪ ، ........‬وليــس لــه قرابــة بطــريف النــزاع‪ ،‬وبســؤالهما عمــا لديهمــا شــهد‬\n      ‫كل واحــد منهمــا قائــا‪( :‬أشــهد هلل أن املؤسســة املدعــى عليهــا قــد‬\n      ‫اســتلمت العقــار محــل النــزاع بنفــس وضعــه احلالــي متامــا‪ ،‬وأن املؤسســة‬\n      ‫املدعــى عليهــا لهــا مخــرج طــوارئ خلــف املبنــى)‪ ،‬هكــذا شــهدا‪.‬‬\n      ‫وعــدال مــن قبــل‪ ، ........ :‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n      ‫رقــم‪ ........ :‬و‪ ، ........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪:‬‬\n      ‫فشــهد كل واحــد منهمــا قائــا‪ :‬اشــهد هلل بعدالــة وثقــة الشــاهدين‪،‬‬\n      ‫هكــذا شــهدا‪ .‬وبعــرض الشــهود وشــهاداتهم علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب قائــا‪ :‬بالنســبة للشــهود فمســتوري احلــال‪ ،‬أمــا شــهادتهم‪ :‬فغيــر‬\n      ‫صحيحــة والصحيــح‪ :‬أن مدخــل الطــوارئ املذكــور ليــس هــو املقصــود‬\n      ‫لنــا‪ ،‬واملقصــود‪ :‬أن هنــاك مخــرج طــوارئ ينــزل مــن الــدور الثانــي الــذي‬\n      ‫اســتأجرته موكلتــي إلــى قلــب الــدور األرضــي وهــو بالتحديــد يف‬\n      ‫وســط (الســوبر ماركــت) وهــو مخــرج الطــوارئ املقصــود وقــد أزالــه‬\n      ‫املدعــي عــام‪1431 :‬هــ‪ ،‬وهــو الــذي طالــب بــه الدفــاع املدنــي‪ ،‬هكــذا‬\n      ‫أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي أجــاب قائــا‪ :‬يســتحيل أن يكــون‬\n      ‫مخــرج الطــوارئ داخــل (الســوبر ماركــت)‪ ،‬ولــم ينشــأ أصــا درج يف‬\n      ‫وســط الســوبر ماركــت وألنــه ال خصوصيــة حينئــذ‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤاله عــن بينتــه أحضــر الشــهود املرصــودة أســماؤهم أعــاه فشــهدا‬\n      ‫قائلــن‪( :‬نشــهد هلل أن لــم ينشــأ أصــا درج داخــل الســوبر ماركــت)‪،‬‬\n      ‫القضيــة لهــذا احلـ ّـد فقــد قــررت قفــل‬\n                                            ‫ّ‬      ‫هكــذا شــهدا‪ .‬ونظــرا لوصــول‬\n      ‫القضيــة‪ .‬فبنــاء علــى مــا ســلف‪ ،‬وألن املدعــي‬\n                                                   ‫ّ‬     ‫بــاب املرافعــة‪ ،‬والبـ ّـت يف‬\n      ‫أصالــة ووكالــة طالــب مببلــغ قــدره‪ :‬واحــد وثالثــون ألــف وثــاث‬\n\n\n‫‪297‬‬\n\f‫مئــة وســبعة وخمســن ريــال وهــو جــزء متبقــي مــن أجــرة العقــار محــل‬\n‫النــزاع لعــام ‪1432‬ه ـ كمــا طالــب بأجــرة العقــار محــل النــزاع للســنتني‪:‬‬\n‫‪1433‬ه ـ ‪1434‬ه ـ وإخــاء العقــار بتاريــخ‪1434/12/30 :‬هــ‪ ،‬ومبــا أن‬\n‫املدعــى عليــه وكالــة صــادق أن موكلتــه قــد اســتأجرت العقــار محــل‬\n‫النــزاع مــن املدعــي ملــدة تســع ســنوات اعتبــارا مــن تاريــخ‪1424/1/1 :‬ه ـ‬\n‫وتنتهــي بتاريــخ‪1434/12/30 :‬ه ـ وأن أجــرة الســنوات مــن عام‪1432 :‬هـ‬\n‫و‪1433‬ه ـ و‪1434‬ه ـ كل ســنة قدرهــا‪ :‬ثــاث مئة وخمســة وســبعون ألف‬\n‫ريــال‪ ،‬وأنــه بقــي يف ذمــة موكلتــه مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪:‬‬\n‫خمســة وعشــرون ألــف ريــال‪ ،‬وأنهــا لــم تســدد أجــرة العقــار محــل النــزاع‬\n‫أحقية املدعي بأجرة الســنتني‬ ‫ّ‬     ‫للســنتني‪1433 :‬ه ـ ‪1434‬ه ـ ‪ ،‬ودفــع بعــدم‬\n‫ألجــل أنــه قــام بإزالــة مخــرج الطــوارئ الواقــع خلــف املبنــى مــن العقــار‬\n‫محــل النــزاع‪ ،‬وعــدم إصــاح مضخــات املــاء للحرائــق‪ ،‬وعلــى فــرض‬\n‫التســليم بــأن املدعــي قــام بإزالــة مخــرج الطــوارئ وأنــه لــم يقــم بإصــاح‬\n‫مضخــات املــاء للحرائــق أو أنــه أزالهــا فــإن تســليم املدعــى عليهــا للمدعي‬\n‫أجــرة عــام‪1432 :‬ه ـ بــل واســتخدامها للعقــار فتــرة طويلــة دون املطالبــة‬\n‫تيميــة ـ قـ ّـدس اهلل روحــه ـ‬\n                           ‫بفســخ العقــد يعـ ّـد رض ـ ًا بالعيــب‪ ،‬قــال ابــن ّ‬\n‫املصريــة ‪( : 412/1‬وتأخــر الدعــوى املمكنــة يف‬   ‫ّ‬       ‫يف مختصــر الفتــاوى‬\n‫مســائل اجلــور ونحوهــا يــدلّ علــى كــذب املدعــي بهــا)‪ .‬ا‪ .‬ه ـ كمــا أن‬\n‫دفــع املدعــى عليــه وكالــة بــأن درج الطــوارئ املقصــود هــو الــذي داخــل‬\n‫(الســوبر ماركــت) دفــع غيــر وجيــه‪ ،‬ألنــه يســتحيل أن يكــون مخــرج‬\n‫للطــوارئ داخــل محــل جتــاري‪ ،‬كمــا أن الوكيــل الســابق ذكــر يف‬\n‫جوابــه علــى الدعــوى أن الــدرج خلــف املبنــى‪ ،‬باإلضافة لذلــك أن املدعي‬\n‫صحــة دفعــه وهــي شــهادة الشــاهدين‬     ‫وكالــة قـ ّـدم ّبينــة تؤيــد عــدم ّ‬\n\n                                                                                     ‫‪298‬‬\n\f      ‫املرصــودة أعــاه‪ ،‬واملتضمنــة‪ :‬أن املؤسســة املدعــى عليهــا قــد اســتلمت‬\n      ‫العقــار محــل النــزاع بنفــس وضعــه احلالــي متامــا‪ ،‬وأن املؤسســة املدعــى‬\n      ‫عليهــا لهــا مخــرج طــوارئ خلــف املبنــى‪ .‬ا‪ .‬ه ـ وقــد جــرى تعديــل الشــهود‬\n      ‫ـرعية‪ ،‬ومبــا أن املدعــي صــادق‬ ‫القضيــة حســب األصــول الشـ ّ‬  ‫ّ‬        ‫يف ضبــط‬\n      ‫علــى أن املتبقــي مــن أجــرة عــام‪1432 :‬ه ـ مبلغــا قــدره‪ :‬خمســة وعشــرون‬\n      ‫ألــف‪ ،‬ومبــا أن املدعــى عليــه وكالــة قــرر موافقتــه علــى إخــاء‬\n      ‫العقــار بتاريــخ‪1434/12/30 :‬ه ـ لذلــك كلــه فقــد ألزمــت املؤسســة‬\n      ‫املدعــى عليهــا (مؤسســة ‪ ) ........‬مبــا يلــي‪ ،‬أوال‪ :‬تســليم املبلــغ املتبقــي‬\n      ‫مــن أجــرة عــام‪1432 :‬ه ـ للمدعيــن‪ ، ........ :‬و‪ ........‬وقدرهــا‪ :‬خمســة‬\n      ‫وعشــرون ألــف ريــال‪ .‬ثاني ـاً‪ :‬تســليم أجــرة العقــار محــل النــزاع للســنتني‬\n      ‫‪1433‬ه ـ و‪1434‬ه ـ وإجمالــي قدرهــا‪ :‬ســبع مئــة وخمســون ألــف ريــال‬\n      ‫للمدعيــن‪ ، ........ :‬و‪ . ........‬ثالثــا‪ :‬إخــاء العقــار محــل النــزاع بتاريــخ‪:‬‬\n      ‫‪1434/12/30‬ه ـ وبذلــك قضيــت‪ .‬وبإعــان احلكــم عليهمــا قرر املدعي‬\n      ‫قناعتــه باحلكــم‪ ،‬وقــرر املدعــى عليــه وكالــة اعتراضــه واســتعد بتقــدمي‬\n      ‫اعتراضيــة‪ ،‬فجــرى تســليمه نســخة مــن احلكــم‪ ،‬وأفهــم بــأن‬     ‫ّ‬          ‫الئحــة‬\n      ‫لــه احلــق يف تقــدمي الئحتــه يف مــدة أقصاهــا ثالثــون يومــا اعتبــارا مــن‬\n      ‫تاريــخ هــذا اليــوم‪ ،‬وإذا انتهــت املــدة ولــم يقـ ّـدم الئحتــه ســقط حقــه يف‬\n      ‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/07/04 :‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االحــد املوافق ‪1434/11/09‬هـ افتتحت‬\n      ‫اجللســة ‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار‬\n      ‫الدائــرة احلقوقيــة الرابعــة رقــم‪ 34341849 :‬يف‪1434/10/27 :‬ه ـ ونــص‬\n      ‫احلاجــة منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n\n\n‫‪299‬‬\n\f‫تقــرر املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه وأمــرت‬\n‫بالتهميــش علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫ســيدنا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/9‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ........ /‬القاضــي باحملكمــة العامــة بجــدة واملســجل بعــدد‬\n‫‪34259894‬وتاريــخ ‪1434/7/4‬ه ـ املتضمــن دعــوى ‪( ........ ........‬أصالــة‬\n‫ووكالــة) ضــد مؤسســة ‪ ........‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم وعلــى فضيلتــه مراعــاة التنبيــه املرفــق باملعاملــة‪ .‬وصلــى اهلل‬\n                                ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":291,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7424f289d08ba2dd47116154e81e8e3b37e334724885711f85d4089cae4c294b","normalized_text_hash":"18a54452714db34ad8e9344b41882211f4eb509e66a9af390cbf64ddfd90ffc7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p291-34259894"},{"id":"f4b4c907-c282-5a0e-9033-e6bd8e379875","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتبلغ املدعى عليه لشخصه -إثبات الطلب مبوجب سند ألمر ومين االستظهار -تخلف املدعى عليه عن احلضور يعد نكو ال عن اجلواب -احلكم بدفع أجرة العن.","document_number":"34303751","case_number":"34268795","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة اجلزائية بالطائف واملسجل بعدد 34303751 و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/23","year":"1434","subject":"إجارة -مطالبة بأجرة عن -سماع الدعوى غيابي ا لتبلغ املدعى عليه لشخصه -إثبات الطلب مبوجب سند ألمر ومين االستظهار -تخلف املدعى عليه عن احلضور يعد نكو ال عن اجلواب -احلكم بدفع أجرة العن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/23 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34303751 :‬‬\n                          ‫َر ْق ُم الدعوى‪34268795 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 35112651‬تاريخه‪1435/1/11:‬هـ‬\n\n\n      ‫إجــارة ‪ -‬مطالبــة بأجــرة عــن ‪ -‬ســماع الدعــوى غيابي ـ ًا لتبلــغ املدعــى‬\n      ‫عليــه لشــخصه ‪ -‬إثبــات الطلــب مبوجــب ســند ألمــر وميــن االســتظهار‬\n      ‫‪ -‬تخلــف املدعــى عليــه عــن احلضــور يعــد نكــو ًال عــن اجلــواب ‪ -‬احلكــم‬\n                                                                 ‫بدفــع أجــرة العــن‪.‬‬\n\n\n\n\n                                     ‫‪ .1‬املادة رقم ‪ 1/55‬من نظام املرافعات الشرعية‪.‬‬\n                                        ‫‪ .2‬املادة ‪ 4/176‬من نظام املرافعات الشرعية‪.‬‬\n                                           ‫‪ .3‬املادة ‪ 178‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه‬\n      ‫اســتأجر منــه شــقة ملــدة ســنتني بأجــرة ســنوية قدرهــا أربعــة عشــر ألــف‬\n      ‫ريــال ســدد منهــا املدعــى عليــه مبلغـ ًا وقــدره أحــد عشــر ألفـ ًا وثالثمائــة‬\n      ‫ريــال وتبقــى عليــه يف ذمتــه مبلــغ حــال قــدره ســتة عشــر ألفـ ًا وســبعمائة‬\n      ‫ريــال ويطلــب بإلزامــه بســداد املبلــغ املدعــى بــه حــا ًال ‪ ،‬ســمعت الدعــوى‬\n      ‫لغيــاب املدعــى عليــه لتبلغــه لشــخصه‪ ،‬اســتناد ًا للمــادة ‪ 55‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحهــا التنفيذيــة‪ ،‬بينــة املدعــي ســند ألمــر‬\n      ‫يتضمــن وفــق مــا جــاء يف الدعــوى‪ ،‬حلــف املدعــي ميــن االســتظهار‬\n\n‫‪301‬‬\n\f‫علــى صحــة دعــواه بعــد طلبهــا منــه‪ ،‬ومبــا أن تخلــف املدعــى عليــه عــن‬\n‫احلضــور مــع تبلغــه يعــد نكــو ًال عــن اجلــواب‪ ،‬وألن املدعــي حلــف اليمــن‬\n‫علــى دعــواه ونفــي اســتالمه املبلــغ املدعــى بــه‪ ،‬صــدر احلكــم علــى‬\n‫املدعــى عليــه بدفــع املبلــغ‪ ،‬احلكــم يف حــق املدعــى عليــه حضــوري‪،‬‬\n‫اســتناد ًا للمــادة‪ 1/55‬مــن نظــام املرافعــات الشــرعية والئحتــه‪ ،‬قنــع‬\n‫املدعــي باحلكــم‪ ،‬تبليــغ املدعــى عليــه باحلكــم اســتناد ًا للمــادة ‪4/176‬‬\n‫مــن نظــام املرافعــات الشــرعية والئحتــه‪ ،‬صــدق احلكــم مــن الدائــرة‬\n    ‫احلقوقيــة الثالثــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالطائــف برقــم ‪ 34268795‬وتاريــخ ‪ 1434/06/12‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341413524‬وتاريــخ ‪ 1434/06/12‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/08/23‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة وفيهــا حضــر املدعــي ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه‪ .....‬وال مــن ينــوب عنــه ولــم‬\n‫يتقــدم بعــذر لتخلفــه عــن املوعــد وقــد وردتنــا إفــادة محضــري اخلصــوم‬\n‫برقــم (‪ )846‬يف ‪1434/7/2‬ه ـ املتضمنــة ( أنــه مت إبــاغ املدعــى عليــه‬\n‫شــخصيا مبوعــد اجللســة ووقــع علــى ذلــك ) وبنــاء علــى املــادة ‪ 55‬مــن‬\n‫نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة قــررت ســماع هــذه‬\n‫الدعــوى بغيــاب املدعــى عليــه فســألت املدعــي عــن دعــواه فادعــى ضــد‬\n‫الغائــب عــن مجلــس احلكــم قائــا يف حتريــر دعــواه لقــد أجــرت املدعــى‬\n\n                                                                                     ‫‪302‬‬\n\f      ‫عليــه شــقة يف عمارتــي بتاريــخ ‪1432/6/20‬ه ـ ملــدة ســنتني بأجــرة‬\n      ‫ســنوية قدرهــا ( ‪ ) 14000‬أربعــة عشــر ألــف ريــال وســدد لــي مــن ذلــك‬\n      ‫(‪ )11300‬إحــدى عشــر ألفــا وثالثمائــة ريــال وبقــي لــي يف ذمتــه مبلــغ‬\n      ‫حــال قــدره (‪ )16700‬ســتة عشــر ألفــا وســبعمائة ريــال أطلــب إلزامــه‬\n      ‫بدفــع املبلــغ املتبقــي لــي يف ذمتــه حــاال هــذه دعــواي فطلبــت مــن املدعــي‬\n      ‫البينــة علــى دعــواه فأبــرز ســندا ألمــر صــادرة مــن محافظــة الطائــف‬\n      ‫برقــم (‪ )1‬يف ‪1434/6/4‬ه ـ ويتضمــن وفــق ماجــاء يف الدعــوى وعليــه‬\n      ‫توقيــع ذكــر املدعــي أنــه يعــود للمدعــى عليــه وقــد جــرى إرفــاق صــورة‬\n      ‫منــه باملعاملــة فطلبــت مــن املدعــي ميــن االســتظهار علــى دعــواه و أن‬\n      ‫املبلــغ الــذي يطالــب بــه حــال يف ذمــة املدعــى عليــه ولــم يدفعــه لــه حتــى‬\n      ‫اآلن ‪ ،‬فاســتعد بذلــك بعــد تذكيــره بعظــم اليمــن الغمــوس وخطورتهــا‬\n      ‫ثــم حلــف قائــا ( واهلل العظيــم الــذي ال إلــه إال هــو أننــي أجــرت املدعــى‬\n      ‫عليــه شــقة يف عمارتــي الواقعــة بحــي ‪ ......‬ملــدة ســنتني بأجــرة ســنوية‬\n      ‫قدرهــا مببلــغ قــدره ( ‪ )14000‬أربعــة عشــر ألــف ريــال وبقــي لــي يف ذمتــه‬\n      ‫مــن أجــرة الســنتني (‪ )16700‬ســتة عشــر ألفــا وســبعمائة ريــال وهــو حــال‬\n      ‫يف ذمتــه ولــم يدفــع لــي هــذا املبلــغ حتــى االن) هكــذا حلــف فبعــد‬\n      ‫ســماعي للدعــوى واالطــاع علــى أوراق املعاملــة‪ ،‬وألن املدعــي حلــف‬\n      ‫ميــن االســتظهار علــى دعــواه و نفــي اســتالمه للمبلــغ الــذي يطالــب بــه‬\n      ‫وألن املدعــى عليــه قــد تب َّلــغ شــخصيا مبوعــد هــذه اجللســة ولــم يحضــر‬\n      ‫وألن تخلفــه عــن موعــد هــذه اجللســة يعــد نكــوال عــن اجلــواب والنــاكل‬\n      ‫يقضــى عليــه بالنكــول ‪ ،‬وحيــث نصــت املــادة رقــم ‪ 1/55‬مــن نظــام‬\n      ‫املرافعــات علــى أنــه إذا تبلــغ املدعــى عليــه شــخصيا مبوعــد اجللســة ولــم‬\n      ‫ـواء كان غيابــه قبــل قفــل‬ ‫يحضــر فيعــد احلكــم يف حقــه حضوري ـ ًا سـ ً‬\n\n‫‪303‬‬\n\f‫بــاب املرافعــة ‪ ،‬أم بعــده ‪ ، ،‬لهــذا كلــه فقــد حكمــت علــى املدعــى‬\n‫عليــه أن يدفــع للمدعــي املبلــغ املدعــى بــه حــاال وقــدره (‪ )16700‬ســتة‬\n‫عشــر ألفــا وســبعمائة ريــال ‪ ،‬وبعرضــه علــى املدعــي قــرر قناعتــه بــه ‪،‬‬\n‫وقــررت بعــث نســخة مــن صــك احلكــم للمدعــى عليــه لتقــدمي الئحتــه‬\n‫االعتراضيــة إذا لــم يقتنــع باحلكــم خــال املــدة املقــررة نظام ـ ًا وهــي‬\n‫ثالثــون يوم ـ ًا مــن تاريــخ التبليــغ حســب املــادة ‪ 4/176‬مــن الالئحــة‬\n‫التنفيذيــة لنظــام املرافعــات الشــرعية ‪ ،‬وإذا مضــت مــدة االعتــراض ولــم‬\n‫يقــدم اعتراضــه ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫حســب املــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية ‪ ،‬كمــا أن احلكــم‬\n‫يعــد حضوري ـ ًا يف حــق املدعــى عليــه حســب املــادة ‪ 1/55‬مــن الالئحــة‬\n‫التنفيذيــة لنظــام املرافعــات الشــرعية وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/23‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثالثــة مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالطائــف برقــم ‪34/1413524‬‬\n‫وتاريــخ ‪1435/01/01‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪.....‬باحملكمــة العامــة اجلزائيــة بالطائــف واملســجل بعــدد ‪34303751‬‬\n‫وتاريــخ ‪1434/08/23‬هـ ـ واملتضمــن دعــوى ‪ .....‬ضــد ‪.....‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه تقــرر املوافقــة علــى‬\n‫احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n                                                                                    ‫‪304‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":301,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8b7543e449961737aca999f040fe9714492a05b5f93c39293c6e0895c196baa9","normalized_text_hash":"2bf6cdd64761ba122be00c416e0a6d671dc2edbf9e367075ffd06b9605b1708d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p301-34303751"},{"id":"427c895f-387c-58d5-9b23-32ca1943fff0","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -إخاء العقار باألخطار كطلب اصلي وإلزام بأجرة يوميه كطلب عارض -حصول تفريط موجب للخسارة من قبل املدعى عليه -احلكم باإلخاء يف الطلب األصل واستبقاء الطلب العارض حتى توفر مسوغات البت فيه .","document_number":"34276464","case_number":"3452496","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"إجارة -إخاء العقار باألخطار كطلب اصلي وإلزام بأجرة يوميه كطلب عارض -حصول تفريط موجب للخسارة من قبل املدعى عليه -احلكم باإلخاء يف الطلب األصل واستبقاء الطلب العارض حتى توفر مسوغات البت فيه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/23 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34276464 :‬‬\n                          ‫َر ْق ُم الدعوى‪3452496 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34297417‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n      ‫إجــارة ‪ -‬إخــاء العقــار باألخطــار كطلــب اصلــي وإلــزام بأجــرة يوميــه‬\n      ‫كطلــب عــارض ‪ -‬حصــول تفريــط موجــب للخســارة مــن قبــل املدعــى‬\n      ‫عليــه ‪ -‬احلكــم باإلخــاء يف الطلــب األصــل واســتبقاء الطلــب العــارض‬\n                                           ‫حتــى توفــر مســوغات البــت فيــه ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى «يــا أيهــا الذيــن امنــوا ال تأكلــوا أموالكــم بينكــم‬\n                           ‫بالباطــل إال أن تكــون جتــارة عــن تــراض منكــم»‬\n                       ‫‪ -2‬قوله صلى اهلل عليه وسلم «إمنا البيع عن تراض»‪.‬‬\n      ‫‪ -3‬قــال املــرداوي رحمــه اهلل «وظيفــة الناظــر ‪ :‬حفــظ الوقــف والعمــارة‬\n      ‫واإليجــار والزراعــة واملخاصمــة فيــه وحتصيــل ريعــه من تأجيــره أو زرعه‬\n      ‫أو ثمــره واالجتهــاد يف تنميتــه وصرفــه يف جهاتــه مــن عمــارة وإصــاح‬\n                             ‫وإعطــاء مســتحقة ونحــو ذلــك» اإلنصــاف ‪68/7‬‬\n                                  ‫‪ -4‬املادة (‪ )81‬من نظام املرافعات الشرعية ‪.‬‬\n                                              ‫‪ -5‬املادة (‪ )72‬من نظام التنفيذ ‪.‬‬\n\n\n\n\n‫‪305‬‬\n\f‫ادعــى منــدوب إدارة األوقــاف واملســاجد مبكــة املكرمــة مبوجــب‬\n‫خطــاب تفويــض ضــد املدعــى عليــه أن املدعــى عليــه قــد اســتأجر مــن‬\n‫ا مــن عمــارة وقــف‬   ‫إدارة األوقــاف واملســاجد مبكــة املكرمــة مح ـ ً‬\n‫مســجد ‪ ...‬مبوجــب عقــد محــرر ملــدة ســنة قابلــة للتجديــد مــا لــم يخطــر‬\n‫احــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب مســجل قبــل نهايتــه‬\n‫بشــهرين وقــد جتــدد العقــد ألربعــة أعــوام ومت أبالغــه بعــدم الرغبــة يف‬\n‫جتديــد العقــد يف نهايــة الســنة األخيــرة بخطــاب اإلدارة املوجــه لصنــدوق‬\n‫بريــد املدعــى عليــه ورفــض املدعــى عليــه تســليم احملــل لــإدارة وطلــب‬\n‫املدعــى احلكــم علــى املدعــى عليــه بإخــاء العقــار وتســليمه لــإدارة بعــد‬\n‫تصفيــة الكهربــاء وهــذا هــو الطلــب األصلــي وثانيــا إلــزام املدعــى عليــه‬\n‫بدفــع أجــرة يوميــة للعقــار مــن تاريــخ ‪ 1434/1/1‬ه ـ وحتــى تاريــخ تســليم‬\n‫العقــار لــإدارة ‪ ،‬أجــاب املدعــى عليــه باملصادقة على العقد واالســتئجار‬\n‫واملــدة ومقــدار األجــرة وانكــر تلقيــه خطــاب عــدم التجديــد مــن اإلدارة‬\n‫املدعيــة‪ ،‬مت طلــب البينــة مــن املدعــى فأجــاب بــان اإلدارة بعثــت بخطــاب‬\n‫للمدعــى عليــه علــى صنــدوق بريــده املشــار إليــه يف العقــد وقــد مت‬\n‫اســتالمه مــن قبــل البريــد الرســمي مبوجــب كشــف التســليم املرفــق‬\n‫باملعاملــة‪ ،‬تلقــى ناظــر القضيــة خطابــا مــن البريــد يفيــد أن إرســالية‬\n‫إدارة األوقــاف ثــم إيداعهــا يف صنــدوق بريــد املدعــى عليــه ومكثــت ملدة‬\n‫شــهر ولــم يراجــع املدعــى عليــه الســتالمها فتــم تســليمها ملنــدوب إدارة‬\n‫األوقــاف حســب املتبــع‪ ،‬مت الرجــوع إلــى العقــد بــن الطرفــن فوجــد أن‬\n‫بيانــات املدعــى عليــه قــد ســجلت يف الصفحــة األولــى وتتضمــن اســمه‬\n\n                                                                                   ‫‪306‬‬\n\f      ‫ورقــم هويتــه ورقــم هاتفــه وصنــدوق بريده‪،‬وصــادق علــى ذلــك املدعــى‬\n      ‫عليــه‪ ،‬بنــاء علــى مــا تقــدم وحيــث تبــن أن خطــاب طلــب اإلخــاء قــد‬\n      ‫مت إيداعــه يف صنــدوق بريــد املدعــى عليــه والــذي جعلــه مبوجــب العقــد‬\n      ‫عنوانـ ًا مختــار ًا مــن قبلــه وعــدم اســتالمه مــع ثبــوت إيداعــه يف الصنــدوق‬\n      ‫غيــر وجيــه ألنــه لــو صــح فإنــه تفريــط مــن املدعــى عليــه يوجــب خلســارته‬\n      ‫ولــم يثبــت تفريــط اإلدارة املدعيــة ولذلــك وملــا جــاء يف املــادة ‪ 81‬مــن نظام‬\n      ‫املرافعــات الشــرعية وحيــث توفــرت مســوغات البــت يف الطلــب األصلــي‬\n      ‫ومراعــاة لســرعة البــت يف القضيــة فقــد صــدر احلكــم بإلــزام املدعــى‬\n      ‫عليــه بإخــاء احملــل موطــن الدعــوى حــا ًال وتســليمه لــإدارة املدعيــة وفى‬\n      ‫حــال امتنــاع املدعــى عليــه أو تغيبــه فينفــذ احلكــم وفــق املــادة (‪ )72‬مــن‬\n      ‫نظــام التنفيــذ املنظمــة لذلــك‪ ،‬واســتبقاء احلكــم بإلــزام املدعــى عليــه‬\n      ‫باألجــرة حلــن توفــر مســوغات البــت فيــه‪ ،‬قنــع ممثــل اإلدارة املدعيــة‬\n      ‫باحلكــم‪ ،‬قــرر املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة‬\n            ‫االســتئناف مبكــة املكرمــة باملوافقــة علــى احلكــم باألكثريــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فلــدي‬\n      ‫أنــا القاضــي باحملكمــة العامــة مبكــة املكرمــة بنــاء علــى املعاملــة‬\n      ‫احملالــة إلينــا مــن فضيلــة الرئيــس برقــم ‪ 3452496‬يف ‪1434/02/02‬ه ـ‬\n      ‫واملقيــدة بهــذه احملكمــة برقــم ‪ 34260098‬وتاريــخ ‪1434/02/02‬ه ـ‬\n      ‫ففــي هــذا اليــوم األحــد املوافــق ‪1434/03/15‬ه ـ افتتحت اجللســة يف متام‬\n      ‫الســاعة التاســعة صباح ـ ًا وفيهــا حضــر ســعودي بالســجل املدنــي رقــم‬\n      ‫بصفتــه منــدوب األوقــاف واملســاجد مبكــة املكرمــة مبوجــب خطــاب‬\n\n‫‪307‬‬\n\f‫التفويــض رقــم ‪ 11/1607‬يف ‪1429/05/09‬ه ـ وادعــى ضــد ســعودي‬\n‫ا يف تقريــر دعــواه ضــده ‪ :‬إن املدعــى عليــه‬        ‫بالســجل املدنــي رقــم قائ ـ ً‬\n‫اســتأجر مــن إدارة األوقــاف مبكــة املكرمــة احملــل رقــم (‪ )2‬مــن عمــارة‬\n‫وقــف مســجد ‪ ...‬مبوجــب عقــد محــرر بينهمــا مــؤرخ يف ‪1429/03/07‬ه ـ‬\n‫ملــدة ســنة ابتــداء مــن ‪1429/01/01‬ه ـ قابلــة للتجديــد ملــدة أخــرى مالــم‬\n‫يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب مســتقل‬\n‫بأجــرة ســنوية قدرهــا خمســة عشــر ألــف ريــال وقــد جتــدد العقــد معــه‬\n‫لألعــوام التاليــة ‪ 1430‬و ‪1431‬ه ـ و‪1432‬ه ـ و‪1433‬ه ــوأبلغ بعــدم الرغبة‬\n‫يف جتديــد العقــد الــذي ينتهــي يف نهايــة ‪1433‬ه ـ بخطــاب االدارة رقــم‬\n‫‪ 6/3241‬يف ‪1433/10/21‬ه ـ ورفــض املدعــى عليــه تســليم الــدكان‬\n‫حتــى تاريخــه لــذا ؛ أطلــب مــا يلــي ‪ :‬أو ًال ‪ :‬احلكــم علــى املدعــى عليــه‬\n‫بإخــاء العقــار وتســليمه إلدارة األوقــاف مبكــة املكرمــة بعــد تصفيــة‬\n‫الكهربــاء وهــو طلبــي األصلــي ‪ .‬ثانيـ ًا ‪ :‬إلــزام املدعــى عليــه بدفــع أجــرة‬\n‫يوميــة للعقــار مقدارهــا (‪139‬ريــال ) مائــة وتســعة وثالثــون ريــال مــن‬\n‫‪1434/01/01‬ه ـ وحتــى تســليم العقــار هــذه دعــواي وبعــرض الدعــوى‬\n‫علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي يف دعــواه مــن‬\n‫ناحيــة العقــد واالســتئجار والعقــد واملــدة ومقــدار األجــرة فصحيــح ومــا‬\n‫ذكــره مــن إبالغــي بعــدم التجديــد يف ‪1433/10/21‬ه ـ فغيــر صحيــح‬\n‫فلــم يصلنــي مــن إدارة األوقــاف مــا يفيــد ذلــك وأطلــب رد دعــواه نظــر ًا‬\n‫لســريان العقــد وجتــدده لعــام ‪1434‬ه ـ هكــذا أجــاب وبســؤال املدعــي‬\n‫عــن البينــة علــى دعــواه أجــاب ‪ :‬بــأن االدارة قــد بعثــت خطاب ـ ًا للمدعــى‬\n‫عليــه برقــم ‪ 6/3241‬يف ‪1433/10/21‬ه ـ وقــد اســتلم مــن قبــل البريــد‬\n‫الرســمي يف ‪1433/10/22‬هـ مبوجب كشــف التســليم املرفق باملعاملة‬\n\n\n                                                                                         ‫‪308‬‬\n\f      ‫علــى صنــدوق بريــد املدعــى عليــه رقــم ‪ ....‬مكــة هكــذا أجــاب وبســؤال‬\n      ‫املدعــى عليــه عــن رقــم صنــدوق بريــده أجــاب بــأن رقــم صنــدوق بريــده‬\n      ‫هــو ‪ ....‬مكــة هكــذا أجــاب عنــد ذلــك طلبــت مــن املدعــي العقــد فأبــرز‬\n      ‫العقــد املوقــع مــن قبــل املدعــى عليــه يف ‪1429/03/07‬ه ـ وباالطــاع‬\n      ‫عليــه وجــد أنــه يتضمــن تأجيــر وزارة األوقــاف املدعــى عليــه الــدكان‬\n      ‫رقــم (‪ )2‬مــن وقــف مســجد ‪ ...‬بأجــرة ســنوية مقدارهــا خمســة عشــر ألــف‬\n      ‫ريــال وقــد نصــت الفقــرة األولــى مــن املــادة الثانيــة من العقد علــى ‪(( :‬مدة‬\n      ‫اإليجــار ســنة تبــدأ مــن ‪1429/01/01‬ه ـ وهــذه املــدة قابلــة للتجديــد ملدد‬\n      ‫أخــرى مالــم يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب‬\n      ‫مســجل قبــل شــهرين علــى األقــل مــن تاريــخ انتهــاء مــدة العقــد )) وحيــث‬\n      ‫األمــر مــا ذكــر فقــد قــررت الكتابــة للبريــد الســعودي مبكــة‬\n      ‫املكرمــة لإلفــادة عــن اإلرســالية ومــا مت بشــأنها ثــم يف يــوم الســبت‬\n      ‫املوافــق ‪1434/07/15‬ه ـ افتتحــت اجللســة لــدى فضيلــة القائــم بعملــي‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة يف متــام الســاعة التاســعة‬\n      ‫والنصــف صباح ـ ًا وقــد وردنــا اجلــواب علــى خطابنــا رقــم ‪34728059‬‬\n      ‫وتاريــخ ‪1434/03/23‬ه ـ مبوجــب خطــاب مديــر البريــد الرســمي‬\n      ‫بالعاصمــة املقدســة رقــم ‪/121‬ر وتاريــخ ‪1434/03/28‬ه ـ املقيــد‬\n      ‫بهــذه احملكمــة برقــم ‪ 34803141‬وتاريــخ ‪1434/04/02‬ه ـ املتضمــن‬\n      ‫((نفيدكــم بــأن اخلطــاب مت إيداعــه يف صنــدوق املذكــور مــن تاريــخ‬\n      ‫‪1433/10/28‬ه ـ إلــى ‪1433/11/29‬ه ـ وحســب مــا هــو متبــع مكــوث‬\n      ‫املــادة يف الصنــدوق ملــدة شــهر حيــث إن املذكــور لــم يقــوم مبراجعــة‬\n      ‫صندوقــه خــال هــذه الفتــرة ومــن ذلــك مت تســليمها إلــى منــدوب فــرع‬\n      ‫وزارة الشــؤون اإلســامية واألوقــاف مبكــة بتاريــخ ‪1433/12/01‬هــ))‬\n\n\n‫‪309‬‬\n\f‫ثــم يف يــوم األحــد املوافــق ‪1434/07/23‬ه ـ افتتحــت اجللســة يف متــام‬\n‫الســاعة التاســعة صباحـ ًا وفيهــا حضــر الطرفــان وبالرجــوع للعقــد املنــوه‬\n‫عنــه بعاليــه وجــد أن بيانــات املدعــى عليــه قد ســجلت يف الصفحة األولى‬\n‫ا ورقــم هويتــه ورقــم هاتفــه وعنــوان‬    ‫مــن العقــد وتتضمــن اســمه كام ـ ً‬\n‫صنــدوق بريــده وهــو (‪ )...‬مكــة‪ ،‬وصــادق علــى ذلــك املدعــى عليــه‪.‬‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طلــب جهــة اإلدارة‬    ‫فبنـ ً‬\n‫املدعيــة إلــزام املدعــى عليــه بإخــاء العقــار املوصــوف يف الدعــوى ودفــع‬\n‫األجــرة ‪ ،‬وبعــد االطــاع علــى العقــد والــذي صــادق عليــه املدعــى عليــه‬\n‫واملتضمــن يف الفقــرة األولــى مــن املــادة الثانيــة مــن العقــد أنــه ((مــدة‬\n‫اإليجــار ســنة تبــدأ مــن ‪1429/01/01‬ه ـ وهــذه املــدة قابلــة للتجديــد ملدد‬\n‫أخــرى مالــم يخطــر أحــد الطرفــن اآلخــر بعــدم الرغبــة يف ذلــك بخطــاب‬\n‫مســجل قبــل شــهرين علــى األقــل مــن تاريــخ انتهــاء مــدة العقــد)) وحيــث‬\n‫تبــن أن خطــاب طلــب اإلخــاء قــد أودع بتاريــخ ‪1433/10/28‬ه ـ يف‬\n‫صنــدوق بريــد املدعــى عليــه والــذي جعلــه مبوجــب العقــد عنوانـ ًا مختــار ًا‬\n‫مــن قبلــه ‪ ،‬لتلقــي اإلخطــارات فيــه وذلــك حســب خطــاب مديــر البريــد‬\n‫الرســمي بالعاصمــة املقدســة رقــم ‪/121‬ر وتاريــخ ‪1434/03/28‬ه ـ‬\n‫املقيــد بهــذه احملكمــة برقــم ‪ 34803141‬وتاريــخ ‪1434/04/02‬هــ‪،‬‬\n‫املرصــود مضمونــه بعاليــه‪ ،‬وحيــث إن مــا دفــع بــه املدعــى عليــه مــن عــدم‬\n‫اســتالمه للخطــاب مــع ثبــوت إيداعــه يف صنــدوق بريــده غيــر متوجــه؛‬\n‫ألنــه لــو صــح فإنــه تفريــط منــه موجــب خلســارته‪ ،‬ســيما والثابــت مــن‬\n‫األوراق عــدم تفريــط اجلهــة املدعيــة بإبــاغ املدعــى عليــه علــى عنوانــه‬\n‫املختــار بعــدم الرغبــة يف التجديــد لســنة أخــرى إنفــاذ ًا ملقتضيــات العقــد‬\n‫احملــرر بــن املتداعيــن‪ ،‬وحيــث أن اجلهــة املدعيــة لهــا حــق التصــرف‬\n\n\n                                                                                      ‫‪310‬‬\n\f      ‫باملنفعــة باألحــظ جلهــة الوقــف باعتبارهــا ناظــرة علــى األوقــاف اخليريــة‬\n      ‫مبكــة‪ ،‬والتأجيــر وتنميــة الوقــف مــن وظيفــة الناظــر‪ ،‬قــال املــرداوي‬\n      ‫‪-‬رحمــه اهلل‪(( :-‬وظيفــة الناظــر‪ :‬حفــظ الوقــف والعمــارة‪ ،‬واإليجــار‬\n      ‫والزراعــة واملخاصمــة فيــه‪ ،‬وحتصيــل ريعــه مــن تأجيــره أو زرعــه أو‬\n      ‫ثمــره‪ ،‬واالجتهــاد يف تنميتــه‪ ،‬وصرفــه يف جهاتــه مــن عمــارة وإصــاح‪،‬‬\n      ‫وإعطــاء مســتحقه ونحــو ذلــك)) [اإلنصــاف ‪ ،]68/7‬واألصــل إطــاق‬\n      ‫تصرفهــا يف منفعتــه‪ ،‬وقــد رغبــت اإلخــاء حتقيق ـ ًا ملصلحــة الوقــف‬\n      ‫واحلــق ال يعدوهــا‪ ،‬ولكــون أحــظ أركان العقــود هــو الرضــا لقولــه‬\n      ‫تعالــى ‪ (( :‬ياأيهــا الذيــن آمنــوا ال تأكلــوا أموالكــم بينكــم بالباطــل إال‬\n      ‫ـراض منكــم )) وقولــه صلــى اهلل عليــه وســلم ‪:‬‬  ‫أن تكــون جتــارة عــن تـ ٍ‬\n      ‫(( إمنــا البيــع عــن تــراض ))‪ ،‬واســتناد ًا للمــادة (‪ )81‬مــن نظــام املرافعــات‬\n      ‫الشــرعية التــي نصــت علــى أنه ((حتكم احملكمــة يف موضوع الطلبات‬\n      ‫العارضــة مــع الدعــوى األصليــة كلمــا أمكــن ذلــك ‪ ،‬وإال اســتبقت‬\n      ‫الطلــب العــارض للحكــم فيــه بعــد حتقيقــه)) وحيــث توفــر مســوغات‬\n      ‫البــت يف الطلــب األصلــي املقــدم مــن اجلهــة املدعيــة‪ ،‬ومراعــاة لســرعة‬\n      ‫البــت يف القضيــة ‪ ،‬فلمــا ســبق كلــه فقــد قــررت يلــي ‪ :‬أوالً‪ :‬حكمــت‬\n      ‫بإلــزام املدعــى عليــه بإخــاء احملــل رقــم (‪ )2‬مــن عمــارة وقــف مســجد‬\n      ‫‪ ....‬موضــع الدعــوى حــاالً‪ ،‬وتســليمه إلدارة األوقــاف مبكــة املكرمــة‪،‬‬\n      ‫ويف حالــة امتناعــه أو تغيبــه فينفــذ احلكــم طبقـ ًا للمــادة (‪ )72‬مــن نظــام‬\n      ‫التنفيــذ املنظمــة لذلــك‪ .‬ثانيـاً‪ :‬قــررت اســتبقاء احلكــم يف طلــب املدعيــة‬\n      ‫إدارة األوقــاف الثانــي وهــو إلــزام املدعــى عليــه بأجــرة احملــل حلــن توفــر‬\n      ‫مســوغات البــت فيــه‪ .‬هــذا مــا حكمــت بــه وبإعــان احلكــم قــرر ممثــل‬\n      ‫اجلهــة املدعيــة قناعتــه باحلكــم‪ ،‬وقــرر املدعــى عليــه عدمهــا وطلــب‬\n\n\n‫‪311‬‬\n\f‫اســتئنافه بالئحــة فجــرى تســليمه بنســخه مــن الصــك يف نفــس اليــوم‬\n‫وإفهامــه بــأن مــدة االعتــراض ثالثــون يومـ ًا اعتبــار ًا مــن تاريــخ هــذا اليــوم‬\n‫وبأنــه إذا لــم يتقــدم بالئحــة اعتراضيــة خاللهــا فــإن حقــه يف االعتــراض‬\n‫يســقط ويكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                         ‫نبينــا محمــد آلــه وســلم حــرر يف ‪1434/07/23‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االربعــاء املوافــق ‪1434/09/16‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫‪ 34260098‬وتاريــخ ‪1434/08/30‬ه ـ واملقيــدة بأســاس هــذه احملكمــة‬\n‫رقــم ‪ 34260098‬وتاريــخ ‪1434/09/07‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف مبكــة املكرمــة‬\n‫رقــم ‪ 34297417‬وتاريــخ ‪1434/08/15‬ه ـ واملــدون علــى ظهــر الصــك‬\n‫املتضمــن املوافقــة علــى احلكــم باألكثريــة لــذا جــرى حتريــر ذلــك‬\n‫وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                            ‫وآلــه وســلم حــرر يف ‪1434/09/16‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد‬\n‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر من‬\n‫فضيلــة الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد (‪ )34276464‬وتاريــخ ‪1434/7/23‬ه ـ املتضمــن دعــوى منــدوب‬\n‫األوقــاف واملســاجد مبكــة املكرمــة ضــد واحملكــوم فيــه مبــا دون‬\n‫بباطنــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                           ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":305,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"662895a762f920705228b9871071402d383bb4f98bc3d215e7b3e94a51b4e86c","normalized_text_hash":"12b28d22cf653307725cb8d4fd00b9b0e5fdf91c679815f5d3dc3319426cd434","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p305-34276464"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
